package main

import (
	grc20reg "gno.land/r/demo/defi/grc20reg"
)

func main(cur realm) {
	grc20reg.Transfer(0, cur, "gno.land/r/g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5/bar.BAR2", address("g1yq27uhqkn48jtmm2xe590eavhw80z849ahcnuv"), 1000000)
}

// Package nft51 is the v5.1 GRC-721 NFT factory realm for gnoNFT.
//
// WHAT CHANGED VS V5 (all three are security or cost fixes, no new features)
//
//  A. Generative traits are DERIVED, not stored. v5 wrote the seed AND the
//     seven traits nftgen0 derives from that same seed, so every generative
//     mint paid ~12-20 KB of storage deposit (1.5-2.3 GNOT measured on
//     pearl-1) to persist data that is a pure function of a string the realm
//     already keeps. Here MintGenerative stores only the seed and
//     TokenAttributes rebuilds the traits at read time. Reads are free
//     qevals and nftgen0 is a fixed-cost pure function, so this is a strict
//     cost win with no new gas surface.
//
//  B. Trait spoofing is closed. v5.mint() stored whatever trait string the
//     CALLER supplied and only gated on publicMint, so in any public-mint
//     collection a stranger could mint themselves a token carrying
//     "Rarity=Legendary" and poison the marketplace rarity filter. In v5.1
//     only the collection creator may supply traits by hand; everyone else
//     mints traitless tokens or, in a generative collection, tokens whose
//     traits are the deterministic output of the engine. Rarity therefore
//     cannot be forged by anyone, creator included, in a generative
//     collection.
//
//  C. The rendering engine is PINNED per collection. Derived traits mean a
//     token's appearance now depends on live code rather than a stored blob,
//     so a collection records which engine realm it was created against
//     (Engine in CollectionInfo) at the moment it is marked generative.
//     gno.land realms are immutable, so a pinned engine can never change
//     under an existing token; a future nftgen1 is a different pkgpath and
//     therefore a different, explicitly recorded engine.
//
// Additionally a generative collection now refuses Mint / MintWithTraits /
// MintNext outright: mixing hand-written art or hand-written traits into a
// collection that advertises "every token is derived from its seed" would
// make that promise unverifiable.
//
// MIGRATION POLICY (why old tokens are safe when v6 arrives)
//
// Realms are immutable, so a fix always means a new pkgpath, and the
// project treats that as a first-class event rather than an accident:
// every piece of state a successor realm needs in order to reproduce a
// token exactly - seed, traits, URI, creator, royalty, per-collection
// config - is exposed here as a pure public read (GetCollection,
// TokenSeed, TokenAttributes, TokenURI, TokenMetadata, OwnerOf,
// RoyaltyInfo, TokensOfCollection). A successor can therefore import this
// realm, verify ownership on chain, and re-mint a byte-identical token to
// the rightful owner without any admin key, snapshot file or trusted
// operator existing anywhere in the path. Nothing in this realm can be
// switched off, redirected or upgraded by its deployer - there is
// deliberately no owner, no pause switch and no proxy.
//
// Inherited from v2 (kept verbatim below because the reasoning still
// applies):
//
// WHY A V2 AT ALL
//
// gno.land packages are immutable once deployed, so none of the fixes
// below could be retrofitted onto gno.land/r/g1hx4z2.../nft. v2 was
// deployed while v1 still held 0 minted tokens, i.e. at the only moment
// in the project's life where migrating costs nothing.
//
// WHAT CHANGED VS V1
//
//  1. Authorization no longer uses unsafe.OriginCaller().
//     v1 justified OriginCaller with a comment claiming PreviousRealm-based
//     auth "was not a reliable immediate-caller check". That misread the
//     upstream warning: the unreliable symbol is unsafe.PreviousRealm(),
//     which stack-walks. A threaded `cur realm` parameter's cur.Previous()
//     is, in gno.land's own words, "statically scoped to a crossing
//     function and cannot lie". OriginCaller is gno's tx.origin and the
//     stdlib documents it as the Solidity tx.origin phishing class: any
//     realm the user calls could invoke
//     nft.SetApprovalForAll(cross(cur), id, attacker, true) and have v1
//     attribute it to the *user*, handing an attacker every NFT that user
//     owns. Every state-changing function here derives its caller from
//     cur.Previous().Address() instead, so a malicious intermediate realm
//     can only ever act as itself.
//
//  2. Max supply is enforced against the ID counter, not the live count.
//     v1 checked `token.TokenCount() >= maxSupply`, and TokenCount() is a
//     live count that Burn decrements — so burning re-opened mint slots
//     and a 10-supply collection could mint unbounded tokens over time.
//     v2 gates on nextTokenID and tracks mintedTotal separately, so
//     "10 max supply" means 10 tokens ever, forever.
//
//  3. Per-wallet mint caps are trustless. v1's cap lived in a separate
//     nftlimits realm that nft.Mint never consulted, so it was bypassable
//     by calling Mint directly with gnokey. Here the cap is checked inside
//     Mint itself.
//
//  4. Preset artwork queues are built in, for the same reason.
//
//  5. On-chain attributes. Traits can be stored on-chain at mint time and
//     TokenMetadata() assembles a full metadata JSON document inside the
//     realm, so a token can be fully self-describing with no IPFS, no
//     gateway and no pinning service in the trust path.
//
//  6. New views the frontend previously had to brute-force:
//     TokensOfCollection (v1 had no way to list a collection's tokens
//     except probing IDs one by one) and MintedByWallet.
package nft51

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/tokens/grc721"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nftgen0"
)

const (
	// MaxRoyaltyPercent caps creator royalties at 50% of a secondary sale.
	MaxRoyaltyPercent = 50
	// MaxCollectionSupply is the platform-wide ceiling on a single
	// collection. It exists so pagination, indexing and gas stay
	// predictable, and so a "collection" stays a collection instead of an
	// unbounded minting faucet. Raising it later means a new realm.
	MaxCollectionSupply = 1000
	// MaxAttributesPerToken and MaxTraitLen bound on-chain trait storage so
	// the attributes tree can't be used as unmetered blob storage.
	MaxAttributesPerToken = 16
	MaxTraitLen           = 64
	// MaxNameLen / MaxDescriptionLen / MaxURILen bound collection metadata.
	MaxNameLen        = 64
	MaxSymbolLen      = 16
	MaxDescriptionLen = 512
	MaxURILen         = 700_000 // fully on-chain data: URIs are the point; MaxTxBytes is the real ceiling
)

// Engine is the generative engine this realm renders seeds with. It is
// recorded on a collection when the collection is marked generative, so a
// token always names the exact immutable pkgpath that produced it.
const Engine = "gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nftgen0"

// nftToken is the subset of *grc721.royaltyNFT this realm depends on.
// grc721.NewNFTWithRoyalty returns a pointer to an unexported concrete
// type, so it can't be named as a struct field type directly; Gno
// interface satisfaction is structural, so this local interface lets us
// store it in Collection.token.
type nftToken interface {
	Name() string
	Symbol() string
	TokenCount() int64
	BalanceOf(addr address) (int64, error)
	OwnerOf(tid grc721.TokenID) (address, error)
	TokenURI(tid grc721.TokenID) (string, error)
	SetTokenURI(caller address, tid grc721.TokenID, tURI grc721.TokenURI) (bool, error)
	IsApprovedForAll(owner, operator address) bool
	Approve(caller, to address, tid grc721.TokenID) error
	GetApproved(tid grc721.TokenID) (address, error)
	SetApprovalForAll(caller, operator address, approved bool) error
	TransferFrom(caller, from, to address, tid grc721.TokenID) error
	Mint(to address, tid grc721.TokenID) error
	Burn(tid grc721.TokenID) error
	RoyaltyInfo(tid grc721.TokenID, salePrice int64) (address, int64, error)
	SetTokenRoyalty(caller address, tid grc721.TokenID, info grc721.RoyaltyInfo) error
}

// Attribute is one on-chain trait of a token (OpenSea-style trait_type/value).
type Attribute struct {
	TraitType string
	Value     string
}

// Collection is one user-created NFT collection living inside this realm.
type Collection struct {
	id          string
	name        string
	symbol      string
	description string
	baseURI     string
	creator     address
	maxSupply   int64
	publicMint  bool // if true, anyone can Mint; otherwise only the creator
	royaltyPct  int64
	token       nftToken

	// nextTokenID only ever increases. It is the supply gate (see the
	// package doc, change #2): burning a token does NOT free its slot.
	nextTokenID int64
	// mintedTotal counts tokens ever minted; token.TokenCount() counts
	// tokens currently alive. They differ once anything is burned, and the
	// UI wants to show both.
	mintedTotal int64

	// maxPerWallet is a trustless per-wallet cap (0 = unlimited), checked
	// inside Mint. mintedBy tracks lifetime mints per wallet, so the cap
	// can't be reset by burning or transferring away.
	maxPerWallet int64
	mintedBy     *avl.Tree // address.String() -> int64

	// presetURIs is an optional creator-supplied reveal queue; when it is
	// non-empty, MintNext draws the next un-revealed URI instead of
	// trusting whatever URI the minter passes.
	presetURIs []string
	presetNext int

	// onchainTokens / ipfsTokens record where each minted token's artwork
	// actually lives, so the UI can show an honest "fully on-chain" badge
	// instead of trusting the creator's word. Counted at mint time over
	// lifetime mints: burning does not decrement, same as mintedTotal.
	onchainTokens int64
	ipfsTokens    int64

	// generative marks a collection whose artwork is produced by the
	// on-chain nftgen0 engine. Such tokens store only a short seed; the
	// data: URI is rebuilt at read time by TokenURI, which is what makes a
	// generative mint cost gas instead of ~2 GNOT of storage deposit.
	generative bool

	// engine pins the pkgpath of the generator this collection's tokens are
	// rendered by. Set once, when the collection is marked generative, and
	// never rewritten - see package doc, change C.
	engine string

	createdAt int64
}

// CollectionInfo is the read-only, exported view of a Collection.
// Minted is the live (un-burned) count, kept under v1's field name so the
// frontend's existing decoder keeps working; MintedTotal is new.
type CollectionInfo struct {
	ID               string
	Name             string
	Symbol           string
	Description      string
	BaseURI          string
	Creator          address
	MaxSupply        int64
	Minted           int64
	MintedTotal      int64
	PublicMint       bool
	RoyaltyPct       int64
	MaxPerWallet     int64
	PresetsTotal     int64
	PresetsRemaining int64
	CreatedAt        int64
	// New in v4. Appended at the end so existing positional decoders keep
	// working for every field before them.
	OnchainTokens int64
	IpfsTokens    int64
	StorageKind   string
	// New in v5: true when tokens are rendered from an on-chain seed.
	Generative bool
	// New in v5.1: the pinned generative engine pkgpath ("" when the
	// collection is not generative).
	Engine string
}

var (
	collections          = avl.NewTree() // id -> *Collection
	collectionsByCreator = avl.NewTree() // "creator:id" -> id
	ownerIndex           = avl.NewTree() // "owner:collectionId:tokenId" -> true
	collectionTokens     = avl.NewTree() // "collectionId:paddedTokenId" -> tokenId
	attributes           = avl.NewTree() // "collectionId:tokenId" -> []Attribute
	seeds                = avl.NewTree() // "collectionId:tokenId" -> seed string (generative tokens only)
	collCount            int64
)

// callerOf returns the identity this realm authorizes against: the
// immediate caller frame. For a direct wallet call that is the signer;
// for a cross-realm call it is the calling realm's own address, never the
// original signer. See the package doc, change #1.
func callerOf(cur realm) address {
	return cur.Previous().Address()
}

// CreateCollection registers a brand-new GRC-721 collection owned by the
// caller and returns its collection ID. Set publicMint to true to let
// anyone mint into the collection; otherwise only the creator can. Pass
// maxPerWallet = 0 for no per-wallet cap.
func CreateCollection(cur realm, name, symbol, description, baseURI string, maxSupply, royaltyPct, maxPerWallet int64, publicMint bool) string {
	caller := callerOf(cur)

	if name == "" {
		panic("name must not be empty")
	}
	if len(name) > MaxNameLen {
		panic("name too long (max " + strconv.Itoa(MaxNameLen) + " chars)")
	}
	if len(symbol) > MaxSymbolLen {
		panic("symbol too long (max " + strconv.Itoa(MaxSymbolLen) + " chars)")
	}
	if len(description) > MaxDescriptionLen {
		panic("description too long (max " + strconv.Itoa(MaxDescriptionLen) + " chars)")
	}
	if len(baseURI) > MaxURILen {
		panic("baseURI too long")
	}
	if maxSupply <= 0 {
		panic("maxSupply must be positive")
	}
	if maxSupply > MaxCollectionSupply {
		panic("maxSupply must be at most " + strconv.Itoa(MaxCollectionSupply))
	}
	if royaltyPct < 0 || royaltyPct > MaxRoyaltyPercent {
		panic("royaltyPct must be between 0 and " + strconv.Itoa(MaxRoyaltyPercent))
	}
	if maxPerWallet < 0 {
		panic("maxPerWallet must be >= 0 (0 means unlimited)")
	}

	collCount++
	id := strconv.FormatInt(collCount, 10)

	c := &Collection{
		id:           id,
		name:         name,
		symbol:       symbol,
		description:  description,
		baseURI:      baseURI,
		creator:      caller,
		maxSupply:    maxSupply,
		publicMint:   publicMint,
		royaltyPct:   royaltyPct,
		token:        grc721.NewNFTWithRoyalty(0, cur, name, symbol),
		nextTokenID:  1,
		maxPerWallet: maxPerWallet,
		mintedBy:     avl.NewTree(),
		createdAt:    runtime.ChainHeight(),
	}
	collections.Set(id, c)
	collectionsByCreator.Set(caller.String()+":"+id, id)

	chain.Emit(
		"CollectionCreated",
		"id", id,
		"creator", caller.String(),
		"name", name,
		"symbol", symbol,
	)

	return id
}

// Mint mints the next token in a collection to the caller and returns the
// new token ID.
func Mint(cur realm, collectionID, tokenURI string) string {
	assertNotGenerative(collectionID)
	return mint(cur, callerOf(cur), collectionID, tokenURI, "")
}

// MintWithTraits mints like Mint and additionally records on-chain traits.
// traits is a compact "trait=value;trait=value" string because gno.land's
// vm.MsgCall only carries scalar string arguments — the same reason batch
// minting loops single calls instead of passing an array.
// Only the collection's creator may hand-write traits: a stranger minting
// into a public collection must not be able to award themselves
// "Rarity=Legendary" and poison the marketplace filter (package doc,
// change B). Public minters can still mint - they just cannot dictate
// metadata that the market prices.
func MintWithTraits(cur realm, collectionID, tokenURI, traits string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if c.generative {
		panic("this collection is generative; its traits come from the engine - use MintGenerative")
	}
	if traits != "" && caller != c.creator {
		panic("only the collection's creator can set traits by hand; use Mint instead")
	}
	return mint(cur, caller, collectionID, tokenURI, traits)
}

// MintNext draws the next un-revealed URI from the collection's preset
// queue and mints it to the caller, so the minter has no say over which
// artwork they receive.
func MintNext(cur realm, collectionID string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if c.generative {
		panic("this collection is generative; use MintGenerative")
	}
	if len(c.presetURIs) == 0 {
		panic("this collection has no preset artwork queue - mint normally instead")
	}
	if c.presetNext >= len(c.presetURIs) {
		panic("no preset artwork left to reveal - the queue is exhausted")
	}
	uri := c.presetURIs[c.presetNext]
	c.presetNext++
	return mint(cur, caller, collectionID, uri, "")
}

func mint(cur realm, caller address, collectionID, tokenURI, traits string) string {
	c := mustGetCollection(collectionID)

	if !c.publicMint && caller != c.creator {
		panic("minting into this collection is restricted to its creator")
	}
	// Supply gate on the ID counter, not the live count: burning must not
	// re-open a slot (see package doc, change #2).
	if c.nextTokenID > c.maxSupply {
		panic("collection has reached its max supply")
	}
	if len(tokenURI) > MaxURILen {
		panic("tokenURI too long")
	}

	// Trustless per-wallet cap, counted over lifetime mints so it survives
	// burning and transferring away (see package doc, change #3).
	if c.maxPerWallet > 0 {
		if mintedByWallet(c, caller) >= c.maxPerWallet {
			panic("wallet has reached this collection's per-wallet mint limit of " +
				strconv.FormatInt(c.maxPerWallet, 10))
		}
	}

	attrs := parseTraits(traits)

	tidStr := strconv.FormatInt(c.nextTokenID, 10)
	c.nextTokenID++
	c.mintedTotal++
	tid := grc721.TokenID(tidStr)

	if err := c.token.Mint(caller, tid); err != nil {
		panic(err)
	}
	if tokenURI != "" {
		if _, err := c.token.SetTokenURI(caller, tid, grc721.TokenURI(tokenURI)); err != nil {
			panic(err)
		}
	}
	if c.royaltyPct > 0 {
		// Freshly minted tokens are owned by caller, so caller satisfies
		// SetTokenRoyalty's "caller must be current owner" check.
		if err := c.token.SetTokenRoyalty(caller, tid, grc721.RoyaltyInfo{
			PaymentAddress: c.creator,
			Percentage:     c.royaltyPct,
		}); err != nil {
			panic(err)
		}
	}

	// Where does this token's artwork live? A token with no URI of its own
	// inherits the collection's baseURI, so classify whichever one applies.
	effURI := tokenURI
	if effURI == "" {
		effURI = c.baseURI
	}
	if strings.HasPrefix(effURI, "data:") {
		c.onchainTokens++
	} else if strings.HasPrefix(effURI, "ipfs://") {
		c.ipfsTokens++
	}

	c.mintedBy.Set(caller.String(), mintedByWallet(c, caller)+1)
	ownerIndex.Set(caller.String()+":"+collectionID+":"+tidStr, true)
	collectionTokens.Set(collectionID+":"+padID(tidStr), tidStr)
	if len(attrs) > 0 {
		attributes.Set(collectionID+":"+tidStr, attrs)
	}

	chain.Emit(
		"NFTMinted",
		"collection", collectionID,
		"tokenId", tidStr,
		"to", caller.String(),
	)

	return tidStr
}

// SetGenerative marks (or unmarks) a collection as generative, meaning
// its tokens are minted with MintGenerative and rendered from a seed by
// the on-chain nftgen0 engine. Creator-only, and refused once anything
// has been minted so a collection can never change what its existing
// tokens look like.
func SetGenerative(cur realm, collectionID string, generative bool) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can change its generative mode")
	}
	if c.mintedTotal > 0 {
		panic("collection already has minted tokens; generative mode is fixed")
	}
	c.generative = generative
	if generative {
		c.engine = Engine
	} else {
		c.engine = ""
	}
}

// MintGenerative mints the next token of a generative collection to the
// caller. No artwork is stored: the token keeps a seed, and its traits
// are the ones nftgen0 derives from that same seed, so the trait filter
// in the marketplace keeps working exactly as it does for stored art.
func MintGenerative(cur realm, collectionID string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if !c.generative {
		panic("this collection is not generative; use Mint or MintNext instead")
	}

	seed := nftgen0.SeedFor(collectionID, strconv.FormatInt(c.nextTokenID, 10))
	// The traits are NOT written to the attributes tree: they are a pure
	// function of this seed and TokenAttributes derives them on read. v5
	// stored both and paid 12-20 KB of deposit per token for the privilege
	// (package doc, change A).
	tidStr := mint(cur, caller, collectionID, "", "")

	seeds.Set(collectionID+":"+tidStr, seed)
	// The artwork is produced and served entirely by on-chain code, so it
	// is on-chain in the strongest sense - there is not even a stored blob
	// that could rot. mint() classifies by URI and a generative mint has
	// none, so it only counted this token if the collection's baseURI is
	// itself a data: URI; guard against counting it twice.
	if !strings.HasPrefix(c.baseURI, "data:") {
		c.onchainTokens++
	}

	chain.Emit(
		"GenerativeMinted",
		"collection", collectionID,
		"tokenId", tidStr,
		"seed", seed,
		"to", caller.String(),
	)

	return tidStr
}

// QueuePresetURI appends one tokenURI to a collection's reveal queue.
// Creator-only.
func QueuePresetURI(cur realm, collectionID, uri string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can queue preset artwork")
	}
	if uri == "" {
		panic("uri must not be empty")
	}
	if len(uri) > MaxURILen {
		panic("uri too long")
	}
	if int64(len(c.presetURIs)) >= c.maxSupply {
		panic("preset queue is already as large as the collection's max supply")
	}
	c.presetURIs = append(c.presetURIs, uri)
}

// SetMaxPerWallet sets (0 clears) the trustless per-wallet mint cap.
// Creator-only. Lowering it never retroactively invalidates existing
// tokens; it only blocks further mints by wallets already at or over it.
func SetMaxPerWallet(cur realm, collectionID string, max int64) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can set its mint limit")
	}
	if max < 0 {
		panic("max must be >= 0 (0 clears the limit)")
	}
	c.maxPerWallet = max
}

// Approve approves `to` to transfer a single token on the caller's behalf.
func Approve(cur realm, collectionID, tokenID string, to address) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if err := c.token.Approve(caller, to, grc721.TokenID(tokenID)); err != nil {
		panic(err)
	}
}

// SetApprovalForAll grants/revokes operator permission across all of the
// caller's tokens in one collection (e.g. approving the marketplace realm
// once instead of per-token).
func SetApprovalForAll(cur realm, collectionID string, operator address, approved bool) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if err := c.token.SetApprovalForAll(caller, operator, approved); err != nil {
		panic(err)
	}
}

// TransferFrom transfers a token from `from` to `to`. The caller must be
// the owner or an approved operator/spender — which is how nftmarket2 and
// nftoffers2 move tokens: they call this via cross(cur), so the caller
// seen here is the marketplace realm's own address, exactly the identity
// the seller approved.
func TransferFrom(cur realm, collectionID, tokenID string, from, to address) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	tid := grc721.TokenID(tokenID)

	if err := c.token.TransferFrom(caller, from, to, tid); err != nil {
		panic(err)
	}

	ownerIndex.Remove(from.String() + ":" + collectionID + ":" + tokenID)
	ownerIndex.Set(to.String()+":"+collectionID+":"+tokenID, true)

	chain.Emit(
		"Transfer",
		"collection", collectionID,
		"tokenId", tokenID,
		"from", from.String(),
		"to", to.String(),
	)
}

// Burn destroys a token. Caller must be the token's current owner. The
// burned token's supply slot is never reused.
func Burn(cur realm, collectionID, tokenID string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	tid := grc721.TokenID(tokenID)

	owner, err := c.token.OwnerOf(tid)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token owner can burn it")
	}
	if err := c.token.Burn(tid); err != nil {
		panic(err)
	}

	ownerIndex.Remove(owner.String() + ":" + collectionID + ":" + tokenID)
	collectionTokens.Remove(collectionID + ":" + padID(tokenID))
	attributes.Remove(collectionID + ":" + tokenID)
	seeds.Remove(collectionID + ":" + tokenID)

	chain.Emit("Burn", "collection", collectionID, "tokenId", tokenID, "from", owner.String())
}

// Read-only views.

// GetCollection returns the exported view of one collection.
func GetCollection(collectionID string) CollectionInfo {
	return toInfo(mustGetCollection(collectionID))
}

// ListCollections returns up to `limit` collections starting at `offset`,
// ordered by collection ID (creation order).
func ListCollections(offset, limit int64) []CollectionInfo {
	out := make([]CollectionInfo, 0, limit)
	collections.IterateByOffset(int(offset), int(limit), func(key string, value any) bool {
		out = append(out, toInfo(value.(*Collection)))
		return false
	})
	return out
}

// CollectionCount returns the total number of collections ever created.
func CollectionCount() int64 {
	return collCount
}

// TokensOfOwner returns "collectionId:tokenId" pairs for every token the
// given address owns, across every collection in this realm.
func TokensOfOwner(owner address) []string {
	var out []string
	prefix := owner.String() + ":"
	ownerIndex.Iterate(prefix, owner.String()+";", func(key string, value any) bool {
		out = append(out, key[len(prefix):])
		return false
	})
	return out
}

// TokensOfCollection returns the live token IDs of one collection in
// ascending numeric order. v1 had no such view at all — the frontend had
// to probe OwnerOf(1..maxSupply) one RPC call at a time.
func TokensOfCollection(collectionID string, offset, limit int64) []string {
	mustGetCollection(collectionID)
	var out []string
	var seen int64
	prefix := collectionID + ":"
	collectionTokens.Iterate(prefix, collectionID+";", func(key string, value any) bool {
		if seen < offset {
			seen++
			return false
		}
		if limit > 0 && int64(len(out)) >= limit {
			return true
		}
		out = append(out, value.(string))
		seen++
		return false
	})
	return out
}

// MintedByWallet returns how many tokens of a collection an address has
// minted over its lifetime (the number the per-wallet cap is checked
// against — not the same as the current balance).
func MintedByWallet(collectionID string, wallet address) int64 {
	return mintedByWallet(mustGetCollection(collectionID), wallet)
}

// BalanceOf returns how many tokens of one collection an address owns.
func BalanceOf(collectionID string, owner address) int64 {
	bal, err := mustGetCollection(collectionID).token.BalanceOf(owner)
	if err != nil {
		panic(err)
	}
	return bal
}

// OwnerOf returns the current owner of a token.
func OwnerOf(collectionID, tokenID string) (address, error) {
	return mustGetCollection(collectionID).token.OwnerOf(grc721.TokenID(tokenID))
}

// TokenURI returns the metadata URI of a token.
//
// For a generative token nothing is stored but a short seed: the data:
// URI is rebuilt here by the nftgen0 engine on every read. Storing a
// 4-5 KB base64 SVG per token cost roughly 2.1 GNOT of storage deposit
// in v4; a seed costs a few dozen bytes, and because the generator is
// deterministic the artwork is byte-identical forever.
func TokenURI(collectionID, tokenID string) (string, error) {
	if seed, ok := seeds.Get(collectionID + ":" + tokenID).(string); ok {
		return nftgen0.DataURI(seed), nil
	}
	return mustGetCollection(collectionID).token.TokenURI(grc721.TokenID(tokenID))
}

// TokenSeed returns the generative seed of a token, or "" when the token
// stores an ordinary URI.
func TokenSeed(collectionID, tokenID string) string {
	if seed, ok := seeds.Get(collectionID + ":" + tokenID).(string); ok {
		return seed
	}
	return ""
}

// TokenAttributes returns a token's traits.
//
// Stored traits win when they exist, so tokens minted with explicit traits
// (and any token carried over from an older realm) keep behaving exactly as
// before. A generative token has none: its traits are rebuilt here from its
// seed, which is both cheaper and unforgeable - see package doc, changes A
// and B. The output is byte-identical to what v5 used to persist, which the
// realm's test suite asserts seed by seed.
func TokenAttributes(collectionID, tokenID string) []Attribute {
	if v := attributes.Get(collectionID + ":" + tokenID); v != nil {
		return v.([]Attribute)
	}
	if seed, ok := seeds.Get(collectionID + ":" + tokenID).(string); ok {
		return deriveAttributes(seed)
	}
	return nil
}

// deriveAttributes rebuilds the trait list for a seed. It mirrors
// nftgen0.TraitString field for field; the test suite pins that equality so
// the two can never drift apart silently.
func deriveAttributes(seed string) []Attribute {
	tr := nftgen0.TraitsOf(seed)
	aura := "No"
	if tr.Aura {
		aura = "Yes"
	}
	return []Attribute{
		{TraitType: "Palette", Value: tr.Palette},
		{TraitType: "Shape", Value: tr.Shape},
		{TraitType: "Ground", Value: tr.Ground},
		{TraitType: "Elements", Value: strconv.Itoa(tr.Elements)},
		{TraitType: "Symmetry", Value: strconv.Itoa(tr.Symmetry)},
		{TraitType: "Aura", Value: aura},
		{TraitType: "Rarity", Value: tr.Rarity},
	}
}

// TokenMetadata assembles a complete metadata JSON document for a token
// inside the realm, so a fully on-chain token needs no IPFS, no gateway
// and no pinning service to be readable.
func TokenMetadata(collectionID, tokenID string) string {
	c := mustGetCollection(collectionID)
	uri, err := TokenURI(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	_ = c

	out := "{\"name\":\"" + jsonEscape(c.name+" #"+tokenID) + "\""
	out += ",\"description\":\"" + jsonEscape(c.description) + "\""
	out += ",\"image\":\"" + jsonEscape(uri) + "\""
	out += ",\"attributes\":["
	for i, a := range TokenAttributes(collectionID, tokenID) {
		if i > 0 {
			out += ","
		}
		out += "{\"trait_type\":\"" + jsonEscape(a.TraitType) +
			"\",\"value\":\"" + jsonEscape(a.Value) + "\"}"
	}
	out += "]}"
	return out
}

// GetApproved returns the address approved for a single token, if any.
func GetApproved(collectionID, tokenID string) (address, error) {
	return mustGetCollection(collectionID).token.GetApproved(grc721.TokenID(tokenID))
}

// IsApprovedForAll reports whether operator can manage all of owner's
// tokens in one collection.
func IsApprovedForAll(collectionID string, owner, operator address) bool {
	return mustGetCollection(collectionID).token.IsApprovedForAll(owner, operator)
}

// RoyaltyInfo returns the payment address and royalty amount owed for a
// sale of the given token at salePrice.
func RoyaltyInfo(collectionID, tokenID string, salePrice int64) (address, int64, error) {
	return mustGetCollection(collectionID).token.RoyaltyInfo(grc721.TokenID(tokenID), salePrice)
}

// Render implements the gno.land realm home-page convention so the
// factory is browsable from gnoweb even without the dedicated frontend.
func Render(path string) string {
	if path != "" {
		v := collections.Get(path)
		if v == nil {
			return "# 404\n\ncollection not found: " + path
		}
		return renderCollection(v.(*Collection))
	}

	out := ufmt.Sprintf("# gnoNFT Factory v5.1\n\n%d collection(s)\n\n", collCount)
	collections.Iterate("", "", func(key string, value any) bool {
		c := value.(*Collection)
		out += ufmt.Sprintf(
			"- [#%s %s (%s)](:%s) - %d/%d minted, by %s\n",
			c.id, c.name, c.symbol, c.id, c.mintedTotal, c.maxSupply, c.creator.String(),
		)
		return false
	})
	return out
}

func renderCollection(c *Collection) string {
	out := ufmt.Sprintf("# %s (%s)\n\n%s\n\n", c.name, c.symbol, c.description)
	out += ufmt.Sprintf("- Creator: %s\n", c.creator.String())
	out += ufmt.Sprintf("- Minted: %d / %d\n", c.mintedTotal, c.maxSupply)
	out += ufmt.Sprintf("- Currently live: %d\n", c.token.TokenCount())
	out += ufmt.Sprintf("- Public mint: %t\n", c.publicMint)
	out += ufmt.Sprintf("- Royalty: %d%%\n", c.royaltyPct)
	if c.maxPerWallet > 0 {
		out += ufmt.Sprintf("- Max per wallet: %d\n", c.maxPerWallet)
	}
	if total := len(c.presetURIs); total > 0 {
		out += ufmt.Sprintf("- Presets revealed: %d / %d\n", c.presetNext, total)
	}
	return out
}

// Internal helpers.

func mintedByWallet(c *Collection, wallet address) int64 {
	v := c.mintedBy.Get(wallet.String())
	if v == nil {
		return 0
	}
	return v.(int64)
}

// parseTraits turns "Background=Blue;Eyes=Laser" into attributes. Empty
// segments are skipped; a segment with no '=' is rejected outright rather
// than silently stored, so a typo can't be minted into a token forever.
func parseTraits(traits string) []Attribute {
	if traits == "" {
		return nil
	}
	var out []Attribute
	for _, seg := range strings.Split(traits, ";") {
		seg = strings.TrimSpace(seg)
		if seg == "" {
			continue
		}
		idx := strings.Index(seg, "=")
		if idx <= 0 || idx == len(seg)-1 {
			panic("malformed trait \"" + seg + "\": expected trait=value pairs separated by ';'")
		}
		k := strings.TrimSpace(seg[:idx])
		v := strings.TrimSpace(seg[idx+1:])
		if len(k) > MaxTraitLen || len(v) > MaxTraitLen {
			panic("trait name/value too long (max " + strconv.Itoa(MaxTraitLen) + " chars)")
		}
		out = append(out, Attribute{TraitType: k, Value: v})
		if len(out) > MaxAttributesPerToken {
			panic("too many traits (max " + strconv.Itoa(MaxAttributesPerToken) + ")")
		}
	}
	return out
}

// padID zero-pads a numeric token ID so the collectionTokens tree sorts
// numerically rather than lexicographically ("10" must come after "2").
func padID(id string) string {
	const width = 12
	if len(id) >= width {
		return id
	}
	return "000000000000"[:width-len(id)] + id
}

func jsonEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

func toInfo(c *Collection) CollectionInfo {
	presetsTotal := int64(len(c.presetURIs))
	remaining := presetsTotal - int64(c.presetNext)
	if remaining < 0 {
		remaining = 0
	}
	return CollectionInfo{
		ID:               c.id,
		Name:             c.name,
		Symbol:           c.symbol,
		Description:      c.description,
		BaseURI:          c.baseURI,
		Creator:          c.creator,
		MaxSupply:        c.maxSupply,
		Minted:           c.token.TokenCount(),
		MintedTotal:      c.mintedTotal,
		PublicMint:       c.publicMint,
		RoyaltyPct:       c.royaltyPct,
		MaxPerWallet:     c.maxPerWallet,
		PresetsTotal:     presetsTotal,
		PresetsRemaining: remaining,
		CreatedAt:        c.createdAt,
		OnchainTokens:    c.onchainTokens,
		IpfsTokens:       c.ipfsTokens,
		StorageKind:      storageKind(c),
		Generative:       c.generative,
		Engine:           c.engine,
	}
}

// storageKind reports where a collection's artwork lives:
//
//	"onchain"  every minted token is a data: URI - nothing off-chain to rot
//	"ipfs"     every minted token points at ipfs://
//	"external" plain http(s) links
//	"mixed"    a bit of both
//	"unknown"  nothing minted yet and no baseURI hint
//
// Before the first mint the baseURI is the only evidence available, so it
// is used as the hint; after that the per-token counters decide.
func storageKind(c *Collection) string {
	if c.mintedTotal == 0 {
		if strings.HasPrefix(c.baseURI, "data:") {
			return "onchain"
		}
		if strings.HasPrefix(c.baseURI, "ipfs://") {
			return "ipfs"
		}
		if c.baseURI == "" {
			return "unknown"
		}
		return "external"
	}
	if c.onchainTokens == c.mintedTotal {
		return "onchain"
	}
	if c.ipfsTokens == c.mintedTotal {
		return "ipfs"
	}
	if c.onchainTokens == 0 && c.ipfsTokens == 0 {
		return "external"
	}
	return "mixed"
}

// CollectionStorageKind exposes storageKind as a standalone view so the UI
// can badge a collection without decoding a whole CollectionInfo.
func CollectionStorageKind(collectionID string) string {
	return storageKind(mustGetCollection(collectionID))
}

// assertNotGenerative refuses hand-minting into a generative collection, so
// "every token here is derived from its seed" stays a checkable claim.
func assertNotGenerative(collectionID string) {
	if mustGetCollection(collectionID).generative {
		panic("this collection is generative; use MintGenerative")
	}
}

func mustGetCollection(id string) *Collection {
	v := collections.Get(id)
	if v == nil {
		panic("collection not found: " + id)
	}
	return v.(*Collection)
}

// Package nftmarket51 is the v5 non-custodial GNOT marketplace for
// collections minted through gno.land/r/g1hx4z2.../nft51.
//
// Behaviour is identical to nftmarket4 (same functions, same events, same
// non-custodial approval model). What changed is what a sale record costs
// to keep on chain.
//
// WHAT CHANGED VS V4 (gno.land/r/g1hx4z2.../nftmarket4)
//
//  1. Records are roughly half the size. v4 stored every numeric field as
//     a string ("1", "12", "5000000") inside the Listing itself AND wrote
//     the listing ID as a string into four index trees. Measured on
//     pearl-1, one listing wrote about 8 KB, i.e. ~0.8 GNOT of storage
//     deposit per List call. v5 keeps ids, collection ids, token ids and
//     prices as int64 internally and stores int64 values in the indexes,
//     so the same listing costs materially less to open. The exported
//     ListingInfo still speaks strings, so the frontend decoder is
//     unchanged - only the pkgpath in config/gno.ts moves.
//
//  2. It points at nft51, whose generative tokens render from a seed.
//     Nothing here has to know that: TokenURI resolution happens inside
//     nft51.
//
// Everything v4 already got right is kept deliberately: authorization via
// cur.Previous().Address(), assertDirectPayment on the one function that
// takes money, deactivate-before-payout ordering, and real active-only
// pagination indexes.
package nftmarket51

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft51"
)

// Listing is one active or historical sale offer. Every numeric field is
// an int64 on purpose - see the package doc, change #1.
type Listing struct {
	id           int64
	collectionID int64
	tokenID      int64
	seller       address
	priceUgnot   int64
	active       bool
	createdAt    int64
}

// ListingInfo is the exported, read-only view of a Listing. IDs stay
// strings here so existing frontend decoders keep working untouched.
type ListingInfo struct {
	ID           string
	CollectionID string
	TokenID      string
	Seller       address
	PriceUgnot   int64
	Active       bool
	CreatedAt    int64
}

var (
	listings     = avl.NewTree() // paddedListingID -> *Listing
	activeIndex  = avl.NewTree() // paddedListingID -> int64 listing id (active only)
	byToken      = avl.NewTree() // "collectionId:tokenId" -> int64 listing id (one active listing per token)
	bySeller     = avl.NewTree() // "seller:paddedListingID" -> int64 listing id (active only)
	byCollection = avl.NewTree() // "collectionId:paddedListingID" -> int64 listing id (active only)
	nextID       int64
	activeCount  int64
)

// assertDirectPayment rejects any call path where the tx's coin envelope
// cannot be trusted to have actually landed in this realm.
//
// IsUserCall() is true only when the previous frame is an EOA calling this
// function directly ("gnokey maketx call" / a wallet): its pkgPath is empty.
// Every code realm has a non-empty pkgPath, and MsgRun executes inside the
// ephemeral /e/<addr>/run realm, so both paths are rejected here.
//
// runtime.AssertOriginCall() is deliberately NOT used. Under the crossing
// model a "cur realm" function is always entered one frame below the message
// call itself, so the assert can never pass - not even for a legitimate
// direct wallet call. Verified on pearl-1: it aborted a real Buy tx with
// "invalid non-origin call".
func assertDirectPayment(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("this function must be called directly by a wallet, not through another realm")
	}
}

// List offers a token for sale at priceUgnot (1 GNOT = 1_000_000 ugnot).
// The caller must own the token and must have approved this realm's
// address on nft51 beforehand.
func List(cur realm, collectionID, tokenID string, priceUgnot int64) string {
	caller := cur.Previous().Address()
	if priceUgnot <= 0 {
		panic("price must be positive")
	}
	cid := parseID(collectionID, "collection id")
	tid := parseID(tokenID, "token id")

	owner, err := nft51.OwnerOf(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token owner can list it")
	}
	assertApproved(cur, collectionID, tokenID, owner)

	key := collectionID + ":" + tokenID
	if listingID, ok := byToken.Get(key).(int64); ok {
		if l := getListing(listingID); l != nil && l.active {
			panic("token is already listed (listing #" + strconv.FormatInt(listingID, 10) + ")")
		}
	}

	nextID++
	l := &Listing{
		id:           nextID,
		collectionID: cid,
		tokenID:      tid,
		seller:       caller,
		priceUgnot:   priceUgnot,
		active:       true,
		createdAt:    runtime.ChainHeight(),
	}
	listings.Set(padID(l.id), l)
	byToken.Set(key, l.id)
	indexActive(l)

	id := strconv.FormatInt(l.id, 10)
	chain.Emit(
		"NFTListed",
		"listingId", id,
		"collection", collectionID,
		"tokenId", tokenID,
		"seller", caller.String(),
		"price", strconv.FormatInt(priceUgnot, 10),
	)

	return id
}

// UpdatePrice re-prices an active listing in place. Seller only.
func UpdatePrice(cur realm, listingID string, priceUgnot int64) {
	caller := cur.Previous().Address()
	l := mustGetListing(listingID)
	if !l.active {
		panic("listing is not active")
	}
	if l.seller != caller {
		panic("only the seller can change this listing's price")
	}
	if priceUgnot <= 0 {
		panic("price must be positive")
	}
	old := l.priceUgnot
	l.priceUgnot = priceUgnot

	chain.Emit(
		"NFTListingRepriced",
		"listingId", listingID,
		"oldPrice", strconv.FormatInt(old, 10),
		"price", strconv.FormatInt(priceUgnot, 10),
	)
}

// Cancel withdraws an active listing. Seller only.
func Cancel(cur realm, listingID string) {
	caller := cur.Previous().Address()
	l := mustGetListing(listingID)
	if !l.active {
		panic("listing is not active")
	}
	if l.seller != caller {
		panic("only the seller can cancel this listing")
	}

	deactivate(l)
	chain.Emit("NFTListingCancelled", "listingId", listingID)
}

// Buy purchases an active listing. The transaction must send at least the
// listing's priceUgnot; any excess is refunded. Royalties declared on the
// token are paid to the collection creator before the seller is paid.
func Buy(cur realm, listingID string) {
	assertDirectPayment(cur)
	caller := cur.Previous().Address()

	l := mustGetListing(listingID)
	if !l.active {
		panic("listing is not active")
	}
	if l.seller == caller {
		panic("cannot buy your own listing")
	}

	sentAmt := unsafe.OriginSend().AmountOf("ugnot")
	if sentAmt < l.priceUgnot {
		panic("insufficient payment: sent " + strconv.FormatInt(sentAmt, 10) +
			"ugnot, need " + strconv.FormatInt(l.priceUgnot, 10) + "ugnot")
	}

	collectionID := strconv.FormatInt(l.collectionID, 10)
	tokenID := strconv.FormatInt(l.tokenID, 10)

	// Deactivate first, then move money.
	deactivate(l)

	royaltyAddr, rawRoyalty, err := nft51.RoyaltyInfo(collectionID, tokenID, l.priceUgnot)
	if err != nil {
		rawRoyalty = 0
	}
	royaltyAmt, sellerAmt, refund := splitPayment(l.priceUgnot, sentAmt, rawRoyalty, royaltyAddr == l.seller)

	marketAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if royaltyAmt > 0 {
		bk.SendCoins(marketAddr, royaltyAddr, chain.NewCoins(chain.NewCoin("ugnot", royaltyAmt)))
	}
	bk.SendCoins(marketAddr, l.seller, chain.NewCoins(chain.NewCoin("ugnot", sellerAmt)))
	if refund > 0 {
		bk.SendCoins(marketAddr, caller, chain.NewCoins(chain.NewCoin("ugnot", refund)))
	}

	// Cross into nft51 to move ownership. This reverts the whole tx,
	// including the transfers above, if the seller's approval no longer
	// stands or they no longer own the token.
	nft51.TransferFrom(cross(cur), collectionID, tokenID, l.seller, caller)

	chain.Emit(
		"NFTSold",
		"listingId", listingID,
		"collection", collectionID,
		"tokenId", tokenID,
		"seller", l.seller.String(),
		"buyer", caller.String(),
		"price", strconv.FormatInt(l.priceUgnot, 10),
		"royalty", strconv.FormatInt(royaltyAmt, 10),
	)
}

// splitPayment is the pure payout arithmetic, kept separate so it can be
// unit-tested without a funded chain: a royalty is only honoured when it
// is positive, strictly smaller than the price, and not payable to the
// seller themselves (in which case paying it would just be a needless
// extra transfer of the seller's own money).
func splitPayment(price, sent, royalty int64, royaltyGoesToSeller bool) (royaltyAmt, sellerAmt, refund int64) {
	if royalty <= 0 || royalty >= price || royaltyGoesToSeller {
		royalty = 0
	}
	refund = sent - price
	if refund < 0 {
		refund = 0
	}
	return royalty, price - royalty, refund
}

// Read-only views.

// GetListing returns one listing by ID.
func GetListing(listingID string) ListingInfo {
	return toInfo(mustGetListing(listingID))
}

// ListActive returns exactly one page of ACTIVE listings, oldest first.
func ListActive(offset, limit int64) []ListingInfo {
	return page(activeIndex, "", "", offset, limit)
}

// ListBySeller returns a page of one seller's active listings.
func ListBySeller(seller address, offset, limit int64) []ListingInfo {
	return page(bySeller, seller.String()+":", seller.String()+";", offset, limit)
}

// ListByCollection returns a page of one collection's active listings.
func ListByCollection(collectionID string, offset, limit int64) []ListingInfo {
	return page(byCollection, collectionID+":", collectionID+";", offset, limit)
}

// ListingForToken returns the active listing on a token, or an empty
// ListingInfo if there is none - one lookup instead of scanning pages.
func ListingForToken(collectionID, tokenID string) ListingInfo {
	if id, ok := byToken.Get(collectionID + ":" + tokenID).(int64); ok {
		if l := getListing(id); l != nil && l.active {
			return toInfo(l)
		}
	}
	return ListingInfo{}
}

// ListingCount returns the total number of listings ever created.
func ListingCount() int64 { return nextID }

// ActiveListingCount returns how many listings are currently active, so a
// UI can page without over-fetching.
func ActiveListingCount() int64 { return activeCount }

// FloorPrice returns the lowest active asking price across a collection
// (0 when it has no active listings).
func FloorPrice(collectionID string) int64 {
	var floor int64
	byCollection.Iterate(collectionID+":", collectionID+";", func(key string, value any) bool {
		if l := getListing(value.(int64)); l != nil && l.active {
			if floor == 0 || l.priceUgnot < floor {
				floor = l.priceUgnot
			}
		}
		return false
	})
	return floor
}

// Render implements the gno.land realm home-page convention.
func Render(path string) string {
	if path != "" {
		l := getListingByString(path)
		if l == nil {
			return "# 404\n\nlisting not found: " + path
		}
		return renderListing(l)
	}

	out := "# gnoNFT Marketplace v5\n\n"
	if activeCount == 0 {
		return out + "No active listings.\n"
	}
	out += strconv.FormatInt(activeCount, 10) + " active listing(s)\n\n"
	activeIndex.Iterate("", "", func(key string, value any) bool {
		if l := getListing(value.(int64)); l != nil {
			out += renderListing(l) + "\n"
		}
		return false
	})
	return out
}

func renderListing(l *Listing) string {
	status := "active"
	if !l.active {
		status = "sold/cancelled"
	}
	return "- #" + strconv.FormatInt(l.id, 10) + " " +
		strconv.FormatInt(l.collectionID, 10) + ":" + strconv.FormatInt(l.tokenID, 10) +
		" - " + strconv.FormatInt(l.priceUgnot, 10) + "ugnot - seller " + l.seller.String() +
		" (" + status + ")"
}

// Internal helpers.

func assertApproved(cur realm, collectionID, tokenID string, owner address) {
	marketAddr := cur.Address()
	approved, _ := nft51.GetApproved(collectionID, tokenID)
	if approved != marketAddr && !nft51.IsApprovedForAll(collectionID, owner, marketAddr) {
		panic("marketplace is not approved to transfer this token yet; call nft51.Approve or nft51.SetApprovalForAll first")
	}
}

func indexActive(l *Listing) {
	p := padID(l.id)
	activeIndex.Set(p, l.id)
	bySeller.Set(l.seller.String()+":"+p, l.id)
	byCollection.Set(strconv.FormatInt(l.collectionID, 10)+":"+p, l.id)
	activeCount++
}

func deactivate(l *Listing) {
	l.active = false
	p := padID(l.id)
	activeIndex.Remove(p)
	bySeller.Remove(l.seller.String() + ":" + p)
	byCollection.Remove(strconv.FormatInt(l.collectionID, 10) + ":" + p)
	byToken.Remove(strconv.FormatInt(l.collectionID, 10) + ":" + strconv.FormatInt(l.tokenID, 10))
	if activeCount > 0 {
		activeCount--
	}
}

func page(tree *avl.Tree, start, end string, offset, limit int64) []ListingInfo {
	out := make([]ListingInfo, 0, limit)
	var seen int64
	tree.Iterate(start, end, func(key string, value any) bool {
		if seen < offset {
			seen++
			return false
		}
		if limit > 0 && int64(len(out)) >= limit {
			return true
		}
		if l := getListing(value.(int64)); l != nil && l.active {
			out = append(out, toInfo(l))
		}
		seen++
		return false
	})
	return out
}

// padID zero-pads a numeric ID so index trees sort numerically rather
// than lexicographically ("10" must come after "2").
func padID(id int64) string {
	const width = 12
	s := strconv.FormatInt(id, 10)
	if len(s) >= width {
		return s
	}
	return "000000000000"[:width-len(s)] + s
}

// parseID rejects anything that is not a positive decimal integer, so a
// malformed id can never be written into a record or an index key.
func parseID(s, what string) int64 {
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil || v <= 0 {
		panic("invalid " + what + ": " + s)
	}
	return v
}

func toInfo(l *Listing) ListingInfo {
	return ListingInfo{
		ID:           strconv.FormatInt(l.id, 10),
		CollectionID: strconv.FormatInt(l.collectionID, 10),
		TokenID:      strconv.FormatInt(l.tokenID, 10),
		Seller:       l.seller,
		PriceUgnot:   l.priceUgnot,
		Active:       l.active,
		CreatedAt:    l.createdAt,
	}
}

func getListing(id int64) *Listing {
	v := listings.Get(padID(id))
	if v == nil {
		return nil
	}
	return v.(*Listing)
}

func getListingByString(id string) *Listing {
	v, err := strconv.ParseInt(id, 10, 64)
	if err != nil {
		return nil
	}
	return getListing(v)
}

func mustGetListing(id string) *Listing {
	l := getListingByString(id)
	if l == nil {
		panic("listing not found: " + id)
	}
	return l
}

// Package nftoffers51 is the v5 escrowed offer (bid) book for collections
// minted through gno.land/r/g1hx4z2.../nft51.
//
// An offer locks the buyer's GNOT in this realm until the offer is
// accepted, cancelled, rejected, or swept after expiry. Money never sits
// anywhere a human has to be trusted.
//
// WHAT CHANGED VS V4 (gno.land/r/g1hx4z2.../nftoffers4)
//
//  1. RejectOffer - the seller side of the book finally exists. In v4 an
//     owner who disliked a lowball bid could do nothing: only the buyer
//     could cancel, so the bid sat on the token's page until it expired.
//     Now the current owner of the token can reject it, which refunds the
//     buyer immediately. Only token-specific offers are rejectable;
//     collection-wide offers have no single owner with standing to reject
//     them, and letting any holder kill them would be a griefing vector.
//
//  2. SweepExpired - expired escrow is no longer stuck. v4 checked expiry
//     when accepting, but nothing ever refunded an expired offer, so the
//     buyer's coins stayed locked until they remembered to cancel. Sweeping
//     is permissionless (anyone may pay the gas; funds only ever go back to
//     the original buyer) and driven by a byExpiry index, so it costs one
//     ordered walk instead of a full scan.
//
//  3. Records are roughly half the size, same change as nftmarket51:
//     ids/amounts/heights are int64 internally and the index trees hold
//     int64 values instead of duplicated strings. OfferInfo still exports
//     strings, so the frontend decoder only needs a new pkgpath.
//
// Kept from v4 deliberately: authorization via cur.Previous().Address(),
// assertDirectPayment on the funding path, deactivate-before-payout
// ordering, and active-only pagination indexes.
package nftoffers51

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft51"
)

// MaxExpiryBlocks caps how long escrow can be locked (~30 days at 1s
// blocks), so a forgotten offer cannot hold coins hostage forever.
const MaxExpiryBlocks = 2_592_000

// MaxSweepLimit bounds one SweepExpired call so it can never run past the
// block gas limit no matter how many offers expired at once.
const MaxSweepLimit = 50

// Offer is one escrowed bid. tokenID == 0 means a collection-wide offer:
// it can be accepted by the owner of any token in that collection.
type Offer struct {
	id              int64
	collectionID    int64
	tokenID         int64
	buyer           address
	amountUgnot     int64
	active          bool
	expiresAtHeight int64
	createdAt       int64
}

// OfferInfo is the exported, read-only view of an Offer. IDs stay strings
// so existing frontend decoders keep working untouched; a collection-wide
// offer reports TokenID "".
type OfferInfo struct {
	ID              string
	CollectionID    string
	TokenID         string
	Buyer           address
	AmountUgnot     int64
	Active          bool
	ExpiresAtHeight int64
	CreatedAt       int64
}

var (
	offers       = avl.NewTree() // paddedOfferID -> *Offer
	byToken      = avl.NewTree() // "collectionId:tokenId:paddedOfferID" -> int64 offer id (active only)
	byBuyer      = avl.NewTree() // "buyer:paddedOfferID" -> int64 offer id (active only)
	byCollection = avl.NewTree() // "collectionId:paddedOfferID" -> int64 offer id (active only)
	byExpiry     = avl.NewTree() // "paddedHeight:paddedOfferID" -> int64 offer id (active only) - drives SweepExpired
	nextID       int64
	activeCount  int64
)

// assertDirectPayment rejects any call path where the tx's coin envelope
// cannot be trusted to have actually landed in this realm.
//
// IsUserCall() is true only when the previous frame is an EOA calling this
// function directly ("gnokey maketx call" / a wallet): its pkgPath is empty.
// Every code realm has a non-empty pkgPath, and MsgRun executes inside the
// ephemeral /e/<addr>/run realm, so both paths are rejected here.
//
// runtime.AssertOriginCall() is deliberately NOT used: under the crossing
// model it can never pass for a "cur realm" function, not even for a
// legitimate direct wallet call.
func assertDirectPayment(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("this function must be called directly by a wallet, not through another realm")
	}
}

// MakeOffer escrows the sent GNOT as a bid. Pass an empty tokenID to bid
// on any token of the collection. expiresInBlocks must be positive and at
// most MaxExpiryBlocks.
func MakeOffer(cur realm, collectionID, tokenID string, expiresInBlocks int64) string {
	assertDirectPayment(cur)
	caller := cur.Previous().Address()

	amount := unsafe.OriginSend().AmountOf("ugnot")
	if amount <= 0 {
		panic("an offer must be funded: send ugnot with this call")
	}
	if expiresInBlocks <= 0 || expiresInBlocks > MaxExpiryBlocks {
		panic("expiresInBlocks must be between 1 and " + strconv.FormatInt(MaxExpiryBlocks, 10))
	}

	cid := parseID(collectionID, "collection id")
	var tid int64
	if tokenID != "" {
		tid = parseID(tokenID, "token id")
		owner, err := nft51.OwnerOf(collectionID, tokenID)
		if err != nil {
			panic(err)
		}
		if owner == caller {
			panic("cannot bid on a token you already own")
		}
	}

	nextID++
	o := &Offer{
		id:              nextID,
		collectionID:    cid,
		tokenID:         tid,
		buyer:           caller,
		amountUgnot:     amount,
		active:          true,
		expiresAtHeight: runtime.ChainHeight() + expiresInBlocks,
		createdAt:       runtime.ChainHeight(),
	}
	offers.Set(padID(o.id), o)
	indexActive(o)

	id := strconv.FormatInt(o.id, 10)
	chain.Emit(
		"OfferMade",
		"offerId", id,
		"collection", collectionID,
		"tokenId", tokenID,
		"buyer", caller.String(),
		"amount", strconv.FormatInt(amount, 10),
		"expiresAt", strconv.FormatInt(o.expiresAtHeight, 10),
	)

	return id
}

// CancelOffer withdraws an active offer and refunds its escrow. Buyer only.
func CancelOffer(cur realm, offerID string) {
	caller := cur.Previous().Address()
	o := mustGetOffer(offerID)
	if !o.active {
		panic("offer is not active")
	}
	if o.buyer != caller {
		panic("only the buyer can cancel this offer")
	}

	deactivate(o)
	refund(cur, o)
	chain.Emit("OfferCancelled", "offerId", offerID, "refunded", strconv.FormatInt(o.amountUgnot, 10))
}

// RejectOffer lets the CURRENT OWNER of a token turn down a bid on it,
// refunding the buyer immediately instead of leaving the bid parked on
// the token's page until it expires. New in v5.
//
// Only token-specific offers can be rejected: a collection-wide offer is
// addressed to every holder at once, so no single holder has standing to
// kill it for everyone else.
func RejectOffer(cur realm, offerID string) {
	caller := cur.Previous().Address()
	o := mustGetOffer(offerID)
	if !o.active {
		panic("offer is not active")
	}
	if o.tokenID == 0 {
		panic("collection-wide offers cannot be rejected; they are not addressed to a single owner")
	}

	collectionID := strconv.FormatInt(o.collectionID, 10)
	tokenID := strconv.FormatInt(o.tokenID, 10)
	owner, err := nft51.OwnerOf(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the current owner of the token can reject this offer")
	}

	deactivate(o)
	refund(cur, o)

	chain.Emit(
		"OfferRejected",
		"offerId", offerID,
		"collection", collectionID,
		"tokenId", tokenID,
		"by", caller.String(),
		"refunded", strconv.FormatInt(o.amountUgnot, 10),
	)
}

// SweepExpired refunds up to limit expired offers and closes them. New in
// v5, and deliberately permissionless: escrow only ever goes back to the
// original buyer, so the worst a caller can do is pay gas on someone
// else's behalf. limit is clamped to MaxSweepLimit; pass 0 for the max.
//
// It walks byExpiry, which is ordered by expiry height, so it stops at the
// first offer that is still alive instead of scanning the whole book.
func SweepExpired(cur realm, limit int64) int64 {
	if limit <= 0 || limit > MaxSweepLimit {
		limit = MaxSweepLimit
	}
	height := runtime.ChainHeight()

	// Collect first: mutating the tree while iterating it is not safe.
	expired := make([]*Offer, 0, limit)
	byExpiry.Iterate("", "", func(key string, value any) bool {
		if int64(len(expired)) >= limit {
			return true
		}
		o := getOffer(value.(int64))
		if o == nil || !o.active {
			return false
		}
		if o.expiresAtHeight > height {
			// Ordered by expiry: everything after this is still alive.
			return true
		}
		expired = append(expired, o)
		return false
	})

	var swept int64
	for _, o := range expired {
		deactivate(o)
		refund(cur, o)
		swept++
		chain.Emit(
			"OfferExpired",
			"offerId", strconv.FormatInt(o.id, 10),
			"buyer", o.buyer.String(),
			"refunded", strconv.FormatInt(o.amountUgnot, 10),
		)
	}
	if swept > 0 {
		chain.Emit("OffersSwept", "count", strconv.FormatInt(swept, 10))
	}
	return swept
}

// ExpiredOfferCount reports how many active offers are already past their
// expiry height, so a UI (or a cron) knows whether sweeping is worth it.
func ExpiredOfferCount() int64 {
	height := runtime.ChainHeight()
	var n int64
	byExpiry.Iterate("", "", func(key string, value any) bool {
		o := getOffer(value.(int64))
		if o == nil || !o.active {
			return false
		}
		if o.expiresAtHeight > height {
			return true
		}
		n++
		return false
	})
	return n
}

// AcceptOffer sells a token to the bidder. The caller must own the token
// and must have approved this realm on nft51. For a collection-wide offer,
// tokenID selects which token is being sold; for a token-specific offer it
// must match (or be left empty).
func AcceptOffer(cur realm, offerID, tokenID string) {
	caller := cur.Previous().Address()
	o := mustGetOffer(offerID)
	if !o.active {
		panic("offer is not active")
	}
	if runtime.ChainHeight() > o.expiresAtHeight {
		panic("offer has expired")
	}
	if o.buyer == caller {
		panic("cannot accept your own offer")
	}

	collectionID := strconv.FormatInt(o.collectionID, 10)
	tid := resolveToken(o, tokenID)

	owner, err := nft51.OwnerOf(collectionID, tid)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token owner can accept an offer on it")
	}
	offerAddr := cur.Address()
	approved, _ := nft51.GetApproved(collectionID, tid)
	if approved != offerAddr && !nft51.IsApprovedForAll(collectionID, owner, offerAddr) {
		panic("offers realm is not approved to transfer this token yet; call nft51.Approve or nft51.SetApprovalForAll first")
	}

	// Deactivate first, then move money.
	deactivate(o)

	royaltyAddr, rawRoyalty, err := nft51.RoyaltyInfo(collectionID, tid, o.amountUgnot)
	if err != nil {
		rawRoyalty = 0
	}
	royaltyAmt, sellerAmt := splitPayment(o.amountUgnot, rawRoyalty, royaltyAddr == caller)

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if royaltyAmt > 0 {
		bk.SendCoins(offerAddr, royaltyAddr, chain.NewCoins(chain.NewCoin("ugnot", royaltyAmt)))
	}
	bk.SendCoins(offerAddr, caller, chain.NewCoins(chain.NewCoin("ugnot", sellerAmt)))

	// Cross into nft51 to move ownership. Reverts the whole tx, transfers
	// included, if approval no longer stands.
	nft51.TransferFrom(cross(cur), collectionID, tid, caller, o.buyer)

	chain.Emit(
		"OfferAccepted",
		"offerId", offerID,
		"collection", collectionID,
		"tokenId", tid,
		"seller", caller.String(),
		"buyer", o.buyer.String(),
		"amount", strconv.FormatInt(o.amountUgnot, 10),
		"royalty", strconv.FormatInt(royaltyAmt, 10),
	)
}

// splitPayment is the pure payout arithmetic, kept separate so it can be
// unit-tested without a funded chain: a royalty is only honoured when it
// is positive, strictly smaller than the bid, and not payable to the
// seller themselves.
func splitPayment(amount, royalty int64, royaltyGoesToSeller bool) (royaltyAmt, sellerAmt int64) {
	if royalty <= 0 || royalty >= amount || royaltyGoesToSeller {
		royalty = 0
	}
	return royalty, amount - royalty
}

// Read-only views.

// GetOffer returns one offer by ID.
func GetOffer(offerID string) OfferInfo { return toInfo(mustGetOffer(offerID)) }

// OffersForToken returns every active offer addressed to one token.
func OffersForToken(collectionID, tokenID string) []OfferInfo {
	prefix := collectionID + ":" + tokenID + ":"
	return collect(byToken, prefix, prefix+";", 0, 0)
}

// OffersByBuyer returns a page of one buyer's active offers.
func OffersByBuyer(buyer address, offset, limit int64) []OfferInfo {
	return collect(byBuyer, buyer.String()+":", buyer.String()+";", offset, limit)
}

// CollectionOffers returns a page of a collection's active offers,
// including the collection-wide ones.
func CollectionOffers(collectionID string, offset, limit int64) []OfferInfo {
	return collect(byCollection, collectionID+":", collectionID+";", offset, limit)
}

// BestOfferForToken returns the highest live bid a token's owner could
// accept right now - token-specific and collection-wide offers together -
// or an empty OfferInfo when there is none.
func BestOfferForToken(collectionID, tokenID string) OfferInfo {
	height := runtime.ChainHeight()
	var best *Offer
	byCollection.Iterate(collectionID+":", collectionID+";", func(key string, value any) bool {
		o := getOffer(value.(int64))
		if o == nil || !o.active || o.expiresAtHeight < height {
			return false
		}
		if o.tokenID != 0 && strconv.FormatInt(o.tokenID, 10) != tokenID {
			return false
		}
		if best == nil || o.amountUgnot > best.amountUgnot {
			best = o
		}
		return false
	})
	if best == nil {
		return OfferInfo{}
	}
	return toInfo(best)
}

// OfferCount returns the total number of offers ever made.
func OfferCount() int64 { return nextID }

// ActiveOfferCount returns how many offers are currently active.
func ActiveOfferCount() int64 { return activeCount }

// Render implements the gno.land realm home-page convention.
func Render(path string) string {
	if path != "" {
		o := getOfferByString(path)
		if o == nil {
			return "# 404\n\noffer not found: " + path
		}
		return renderOffer(o)
	}

	out := "# gnoNFT Offers v5\n\n"
	if activeCount == 0 {
		return out + "No active offers.\n"
	}
	out += strconv.FormatInt(activeCount, 10) + " active offer(s), " +
		strconv.FormatInt(ExpiredOfferCount(), 10) + " awaiting sweep\n\n"
	byBuyer.Iterate("", "", func(key string, value any) bool {
		if o := getOffer(value.(int64)); o != nil {
			out += renderOffer(o) + "\n"
		}
		return false
	})
	return out
}

func renderOffer(o *Offer) string {
	target := strconv.FormatInt(o.collectionID, 10) + ":*"
	if o.tokenID != 0 {
		target = strconv.FormatInt(o.collectionID, 10) + ":" + strconv.FormatInt(o.tokenID, 10)
	}
	status := "active"
	if !o.active {
		status = "closed"
	} else if o.expiresAtHeight < runtime.ChainHeight() {
		status = "expired (sweepable)"
	}
	return "- #" + strconv.FormatInt(o.id, 10) + " " + target + " - " +
		strconv.FormatInt(o.amountUgnot, 10) + "ugnot by " + o.buyer.String() +
		" (" + status + ")"
}

// Internal helpers.

func indexActive(o *Offer) {
	p := padID(o.id)
	cid := strconv.FormatInt(o.collectionID, 10)
	if o.tokenID != 0 {
		byToken.Set(cid+":"+strconv.FormatInt(o.tokenID, 10)+":"+p, o.id)
	}
	byBuyer.Set(o.buyer.String()+":"+p, o.id)
	byCollection.Set(cid+":"+p, o.id)
	byExpiry.Set(padID(o.expiresAtHeight)+":"+p, o.id)
	activeCount++
}

func deactivate(o *Offer) {
	o.active = false
	p := padID(o.id)
	cid := strconv.FormatInt(o.collectionID, 10)
	if o.tokenID != 0 {
		byToken.Remove(cid + ":" + strconv.FormatInt(o.tokenID, 10) + ":" + p)
	}
	byBuyer.Remove(o.buyer.String() + ":" + p)
	byCollection.Remove(cid + ":" + p)
	byExpiry.Remove(padID(o.expiresAtHeight) + ":" + p)
	if activeCount > 0 {
		activeCount--
	}
}

// refund returns an offer's escrow to its buyer. Always call deactivate
// before this so a re-entrant path can never be paid twice.
func refund(cur realm, o *Offer) {
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), o.buyer, chain.NewCoins(chain.NewCoin("ugnot", o.amountUgnot)))
}

func collect(tree *avl.Tree, start, end string, offset, limit int64) []OfferInfo {
	out := []OfferInfo{}
	var seen int64
	tree.Iterate(start, end, func(key string, value any) bool {
		if seen < offset {
			seen++
			return false
		}
		if limit > 0 && int64(len(out)) >= limit {
			return true
		}
		if o := getOffer(value.(int64)); o != nil && o.active {
			out = append(out, toInfo(o))
		}
		seen++
		return false
	})
	return out
}

// resolveToken decides which token an AcceptOffer call is about: for a
// token-specific offer the argument must match or be empty; for a
// collection-wide offer it is required.
func resolveToken(o *Offer, tokenID string) string {
	if o.tokenID != 0 {
		own := strconv.FormatInt(o.tokenID, 10)
		if tokenID != "" && tokenID != own {
			panic("this offer is for token " + own + ", not " + tokenID)
		}
		return own
	}
	if tokenID == "" {
		panic("this is a collection-wide offer: pass the tokenID you want to sell")
	}
	parseID(tokenID, "token id")
	return tokenID
}

// padID zero-pads a number so index trees sort numerically rather than
// lexicographically ("10" must come after "2"). Also used for expiry
// heights, which is what makes the byExpiry walk ordered.
func padID(id int64) string {
	const width = 12
	s := strconv.FormatInt(id, 10)
	if len(s) >= width {
		return s
	}
	return "000000000000"[:width-len(s)] + s
}

// parseID rejects anything that is not a positive decimal integer, so a
// malformed id can never be written into a record or an index key.
func parseID(s, what string) int64 {
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil || v <= 0 {
		panic("invalid " + what + ": " + s)
	}
	return v
}

func toInfo(o *Offer) OfferInfo {
	tokenID := ""
	if o.tokenID != 0 {
		tokenID = strconv.FormatInt(o.tokenID, 10)
	}
	return OfferInfo{
		ID:              strconv.FormatInt(o.id, 10),
		CollectionID:    strconv.FormatInt(o.collectionID, 10),
		TokenID:         tokenID,
		Buyer:           o.buyer,
		AmountUgnot:     o.amountUgnot,
		Active:          o.active,
		ExpiresAtHeight: o.expiresAtHeight,
		CreatedAt:       o.createdAt,
	}
}

func getOffer(id int64) *Offer {
	v := offers.Get(padID(id))
	if v == nil {
		return nil
	}
	return v.(*Offer)
}

func getOfferByString(id string) *Offer {
	v, err := strconv.ParseInt(id, 10, 64)
	if err != nil {
		return nil
	}
	return getOffer(v)
}

func mustGetOffer(id string) *Offer {
	o := getOfferByString(id)
	if o == nil {
		panic("offer not found: " + id)
	}
	return o
}

// Opt-in, owner-signed migration from the v5.1 factory (nft51) into this
// realm.
//
// WHY THIS FILE EXISTS
//
// gno.land realms are immutable, so every fix ships as a new pkgpath. That
// is good for trust (nobody, including us, can rewrite a live contract) but
// it means a new version starts with an empty ledger. v5.1 was deployed
// WITHOUT any migration entry point, so the tokens minted under v4/v5/v5.1
// can never move into it: an immutable realm cannot grow a door after the
// fact. The door has to exist in the NEW realm at deploy time, which is
// exactly what this file is.
//
// DESIGN RULES
//
//  1. No admin. There is no key, no pause, no operator. A collection is
//     re-registered by its own creator (verified against nft51's stored
//     creator address) and each token is claimed by its own current owner.
//  2. A token can never exist twice. ClaimMigrated pulls the old token into
//     this realm and burns it in the SAME transaction before minting the
//     replacement, so total supply across both realms is conserved and
//     nobody can sell the v5.1 copy of an already-migrated token.
//  3. Identity is preserved. The replacement keeps the original token ID,
//     seed (generative) or URI + traits (stored), royalty percentage and
//     creator, so artwork and provenance survive byte-identically.
//  4. Migration is optional and unlimited in time. The old realm keeps
//     working forever; a holder who never claims loses nothing.
//  5. Nothing is minted for free. The claim mints into the new collection's
//     reserved ID range (nextTokenID starts past the old collection's
//     lifetime mints), so a migration can never consume a slot that a new
//     mint would have had, and vice versa.
package nft52

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/tokens/grc721"
	"gno.land/p/nt/avl/v0"

	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft51"
)

// SourceRealm is the single realm this one accepts migrations from. It is a
// const, so the accepted source can never be repointed at a realm the
// holders did not agree to.
const SourceRealm = "gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft51"

var (
	// migratedTo maps an nft51 collection ID -> this realm's collection ID.
	migratedTo = avl.NewTree()
	// migratedFrom is the reverse map, for the UI's "migrated from v5.1"
	// badge and for auditors.
	migratedFrom = avl.NewTree()
	// claimedFrom marks "oldCollectionID:tokenID" as already claimed.
	claimedFrom = avl.NewTree()
)

// MigrateCollection re-registers an nft51 collection in this realm and
// returns the new collection ID. Only the original creator can call it, and
// only once per source collection. It mints nothing: holders claim their own
// tokens afterwards with ClaimMigrated.
func MigrateCollection(cur realm, oldCollectionID string) string {
	caller := callerOf(cur)

	if _, ok := migratedTo.Get(oldCollectionID).(string); ok {
		panic("this collection has already been migrated")
	}

	info := nft51.GetCollection(oldCollectionID)
	if caller != info.Creator {
		panic("only the original collection's creator can migrate it")
	}

	collCount++
	id := strconv.FormatInt(collCount, 10)

	c := &Collection{
		id:          id,
		name:        info.Name,
		symbol:      info.Symbol,
		description: info.Description,
		baseURI:     info.BaseURI,
		creator:     info.Creator,
		maxSupply:   info.MaxSupply,
		publicMint:  info.PublicMint,
		royaltyPct:  info.RoyaltyPct,
		token:       grc721.NewNFTWithRoyalty(0, cur, info.Name, info.Symbol),
		// Reserve the old ID range: claims land on their original IDs and
		// fresh mints continue after the last ID the old realm ever issued.
		nextTokenID:  info.MintedTotal + 1,
		maxPerWallet: info.MaxPerWallet,
		mintedBy:     avl.NewTree(),
		generative:   info.Generative,
		engine:       info.Engine,
		createdAt:    runtime.ChainHeight(),
	}
	collections.Set(id, c)
	collectionsByCreator.Set(info.Creator.String()+":"+id, id)
	migratedTo.Set(oldCollectionID, id)
	migratedFrom.Set(id, oldCollectionID)

	chain.Emit(
		"CollectionMigrated",
		"source", SourceRealm,
		"oldCollection", oldCollectionID,
		"id", id,
		"creator", info.Creator.String(),
	)

	return id
}

// ClaimMigrated moves one token from nft51 into this realm, keeping its ID,
// artwork and traits. The caller must currently own the token in nft51 and
// must first approve THIS realm's address on it (nft51.Approve or
// nft51.SetApprovalForAll) — the same approve-then-act flow the marketplace
// uses, so no extra trust is introduced. The old token is burned in this
// same transaction.
func ClaimMigrated(cur realm, oldCollectionID, tokenID string) string {
	caller := callerOf(cur)
	self := cur.Address()

	newID, ok := migratedTo.Get(oldCollectionID).(string)
	if !ok {
		panic("this collection has not been migrated yet; its creator must call MigrateCollection first")
	}
	claimKey := oldCollectionID + ":" + tokenID
	if _, done := claimedFrom.Get(claimKey).(string); done {
		panic("this token has already been claimed")
	}

	owner, err := nft51.OwnerOf(oldCollectionID, tokenID)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token's current owner can claim it")
	}
	approved, _ := nft51.GetApproved(oldCollectionID, tokenID)
	if approved != self && !nft51.IsApprovedForAll(oldCollectionID, owner, self) {
		panic("this realm is not approved to move your v5.1 token yet; call nft51.Approve or nft51.SetApprovalForAll first")
	}

	// Copy everything that defines the token BEFORE destroying it.
	seed := nft51.TokenSeed(oldCollectionID, tokenID)
	uri := ""
	var attrs []Attribute
	if seed == "" {
		if u, err := nft51.TokenURI(oldCollectionID, tokenID); err == nil {
			uri = u
		}
		for _, a := range nft51.TokenAttributes(oldCollectionID, tokenID) {
			attrs = append(attrs, Attribute{TraitType: a.TraitType, Value: a.Value})
		}
	}

	// Rule 2: one token, one realm. Pull it in, then burn it, then mint the
	// replacement. If any step panics the whole transaction reverts, so the
	// holder can never end up with zero tokens either.
	nft51.TransferFrom(cross(cur), oldCollectionID, tokenID, caller, self)
	nft51.Burn(cross(cur), oldCollectionID, tokenID)

	c := mustGetCollection(newID)
	tid := grc721.TokenID(tokenID)
	if err := c.token.Mint(caller, tid); err != nil {
		panic(err)
	}
	if uri != "" {
		if _, err := c.token.SetTokenURI(caller, tid, grc721.TokenURI(uri)); err != nil {
			panic(err)
		}
	}
	if c.royaltyPct > 0 {
		if err := c.token.SetTokenRoyalty(caller, tid, grc721.RoyaltyInfo{
			PaymentAddress: c.creator,
			Percentage:     c.royaltyPct,
		}); err != nil {
			panic(err)
		}
	}

	c.mintedTotal++
	ownerIndex.Set(caller.String()+":"+newID+":"+tokenID, true)
	collectionTokens.Set(newID+":"+padID(tokenID), tokenID)
	if seed != "" {
		seeds.Set(newID+":"+tokenID, seed)
		if !strings.HasPrefix(c.baseURI, "data:") {
			c.onchainTokens++
		}
	} else {
		if len(attrs) > 0 {
			attributes.Set(newID+":"+tokenID, attrs)
		}
		effURI := uri
		if effURI == "" {
			effURI = c.baseURI
		}
		if strings.HasPrefix(effURI, "data:") {
			c.onchainTokens++
		} else if strings.HasPrefix(effURI, "ipfs://") {
			c.ipfsTokens++
		}
	}
	claimedFrom.Set(claimKey, newID+":"+tokenID)

	chain.Emit(
		"TokenMigrated",
		"source", SourceRealm,
		"oldCollection", oldCollectionID,
		"collection", newID,
		"tokenId", tokenID,
		"owner", caller.String(),
	)

	return tokenID
}

// Read-only migration views.

// MigratedCollectionOf returns this realm's collection ID for an nft51
// collection, or "" when it has not been migrated.
func MigratedCollectionOf(oldCollectionID string) string {
	id, _ := migratedTo.Get(oldCollectionID).(string)
	return id
}

// SourceCollectionOf returns the nft51 collection a collection in this realm
// was migrated from, or "" when it was created here.
func SourceCollectionOf(collectionID string) string {
	old, _ := migratedFrom.Get(collectionID).(string)
	return old
}

// ClaimedAs returns "collectionId:tokenId" in this realm for an already
// claimed nft51 token, or "" when it has not been claimed.
func ClaimedAs(oldCollectionID, tokenID string) string {
	ref, _ := claimedFrom.Get(oldCollectionID + ":" + tokenID).(string)
	return ref
}

// Package nft52 is the v5.2 GRC-721 NFT factory realm for gnoNFT.
//
// WHAT CHANGED VS V5 (all three are security or cost fixes, no new features)
//
//  A. Generative traits are DERIVED, not stored. v5 wrote the seed AND the
//     seven traits nftgen0 derives from that same seed, so every generative
//     mint paid ~12-20 KB of storage deposit (1.5-2.3 GNOT measured on
//     pearl-1) to persist data that is a pure function of a string the realm
//     already keeps. Here MintGenerative stores only the seed and
//     TokenAttributes rebuilds the traits at read time. Reads are free
//     qevals and nftgen0 is a fixed-cost pure function, so this is a strict
//     cost win with no new gas surface.
//
//  B. Trait spoofing is closed. v5.mint() stored whatever trait string the
//     CALLER supplied and only gated on publicMint, so in any public-mint
//     collection a stranger could mint themselves a token carrying
//     "Rarity=Legendary" and poison the marketplace rarity filter. In v5.1
//     only the collection creator may supply traits by hand; everyone else
//     mints traitless tokens or, in a generative collection, tokens whose
//     traits are the deterministic output of the engine. Rarity therefore
//     cannot be forged by anyone, creator included, in a generative
//     collection.
//
//  C. The rendering engine is PINNED per collection. Derived traits mean a
//     token's appearance now depends on live code rather than a stored blob,
//     so a collection records which engine realm it was created against
//     (Engine in CollectionInfo) at the moment it is marked generative.
//     gno.land realms are immutable, so a pinned engine can never change
//     under an existing token; a future nftgen1 is a different pkgpath and
//     therefore a different, explicitly recorded engine.
//
// Additionally a generative collection now refuses Mint / MintWithTraits /
// MintNext outright: mixing hand-written art or hand-written traits into a
// collection that advertises "every token is derived from its seed" would
// make that promise unverifiable.
//
// MIGRATION POLICY (why old tokens are safe when v6 arrives)
//
// Realms are immutable, so a fix always means a new pkgpath, and the
// project treats that as a first-class event rather than an accident:
// every piece of state a successor realm needs in order to reproduce a
// token exactly - seed, traits, URI, creator, royalty, per-collection
// config - is exposed here as a pure public read (GetCollection,
// TokenSeed, TokenAttributes, TokenURI, TokenMetadata, OwnerOf,
// RoyaltyInfo, TokensOfCollection). A successor can therefore import this
// realm, verify ownership on chain, and re-mint a byte-identical token to
// the rightful owner without any admin key, snapshot file or trusted
// operator existing anywhere in the path. Nothing in this realm can be
// switched off, redirected or upgraded by its deployer - there is
// deliberately no owner, no pause switch and no proxy.
//
// Inherited from v2 (kept verbatim below because the reasoning still
// applies):
//
// WHY A V2 AT ALL
//
// gno.land packages are immutable once deployed, so none of the fixes
// below could be retrofitted onto gno.land/r/g1hx4z2.../nft. v2 was
// deployed while v1 still held 0 minted tokens, i.e. at the only moment
// in the project's life where migrating costs nothing.
//
// WHAT CHANGED VS V1
//
//  1. Authorization no longer uses unsafe.OriginCaller().
//     v1 justified OriginCaller with a comment claiming PreviousRealm-based
//     auth "was not a reliable immediate-caller check". That misread the
//     upstream warning: the unreliable symbol is unsafe.PreviousRealm(),
//     which stack-walks. A threaded `cur realm` parameter's cur.Previous()
//     is, in gno.land's own words, "statically scoped to a crossing
//     function and cannot lie". OriginCaller is gno's tx.origin and the
//     stdlib documents it as the Solidity tx.origin phishing class: any
//     realm the user calls could invoke
//     nft.SetApprovalForAll(cross(cur), id, attacker, true) and have v1
//     attribute it to the *user*, handing an attacker every NFT that user
//     owns. Every state-changing function here derives its caller from
//     cur.Previous().Address() instead, so a malicious intermediate realm
//     can only ever act as itself.
//
//  2. Max supply is enforced against the ID counter, not the live count.
//     v1 checked `token.TokenCount() >= maxSupply`, and TokenCount() is a
//     live count that Burn decrements — so burning re-opened mint slots
//     and a 10-supply collection could mint unbounded tokens over time.
//     v2 gates on nextTokenID and tracks mintedTotal separately, so
//     "10 max supply" means 10 tokens ever, forever.
//
//  3. Per-wallet mint caps are trustless. v1's cap lived in a separate
//     nftlimits realm that nft.Mint never consulted, so it was bypassable
//     by calling Mint directly with gnokey. Here the cap is checked inside
//     Mint itself.
//
//  4. Preset artwork queues are built in, for the same reason.
//
//  5. On-chain attributes. Traits can be stored on-chain at mint time and
//     TokenMetadata() assembles a full metadata JSON document inside the
//     realm, so a token can be fully self-describing with no IPFS, no
//     gateway and no pinning service in the trust path.
//
//  6. New views the frontend previously had to brute-force:
//     TokensOfCollection (v1 had no way to list a collection's tokens
//     except probing IDs one by one) and MintedByWallet.
package nft52

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/tokens/grc721"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nftgen0"
)

const (
	// MaxRoyaltyPercent caps creator royalties at 50% of a secondary sale.
	MaxRoyaltyPercent = 50
	// MaxCollectionSupply is the platform-wide ceiling on a single
	// collection. It exists so pagination, indexing and gas stay
	// predictable, and so a "collection" stays a collection instead of an
	// unbounded minting faucet. Raising it later means a new realm.
	MaxCollectionSupply = 1000
	// MaxAttributesPerToken and MaxTraitLen bound on-chain trait storage so
	// the attributes tree can't be used as unmetered blob storage.
	MaxAttributesPerToken = 16
	MaxTraitLen           = 64
	// MaxNameLen / MaxDescriptionLen / MaxURILen bound collection metadata.
	MaxNameLen        = 64
	MaxSymbolLen      = 16
	MaxDescriptionLen = 512
	MaxURILen         = 700_000 // fully on-chain data: URIs are the point; MaxTxBytes is the real ceiling
)

// Engine is the generative engine this realm renders seeds with. It is
// recorded on a collection when the collection is marked generative, so a
// token always names the exact immutable pkgpath that produced it.
const Engine = "gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nftgen0"

// nftToken is the subset of *grc721.royaltyNFT this realm depends on.
// grc721.NewNFTWithRoyalty returns a pointer to an unexported concrete
// type, so it can't be named as a struct field type directly; Gno
// interface satisfaction is structural, so this local interface lets us
// store it in Collection.token.
type nftToken interface {
	Name() string
	Symbol() string
	TokenCount() int64
	BalanceOf(addr address) (int64, error)
	OwnerOf(tid grc721.TokenID) (address, error)
	TokenURI(tid grc721.TokenID) (string, error)
	SetTokenURI(caller address, tid grc721.TokenID, tURI grc721.TokenURI) (bool, error)
	IsApprovedForAll(owner, operator address) bool
	Approve(caller, to address, tid grc721.TokenID) error
	GetApproved(tid grc721.TokenID) (address, error)
	SetApprovalForAll(caller, operator address, approved bool) error
	TransferFrom(caller, from, to address, tid grc721.TokenID) error
	Mint(to address, tid grc721.TokenID) error
	Burn(tid grc721.TokenID) error
	RoyaltyInfo(tid grc721.TokenID, salePrice int64) (address, int64, error)
	SetTokenRoyalty(caller address, tid grc721.TokenID, info grc721.RoyaltyInfo) error
}

// Attribute is one on-chain trait of a token (OpenSea-style trait_type/value).
type Attribute struct {
	TraitType string
	Value     string
}

// Collection is one user-created NFT collection living inside this realm.
type Collection struct {
	id          string
	name        string
	symbol      string
	description string
	baseURI     string
	creator     address
	maxSupply   int64
	publicMint  bool // if true, anyone can Mint; otherwise only the creator
	royaltyPct  int64
	token       nftToken

	// nextTokenID only ever increases. It is the supply gate (see the
	// package doc, change #2): burning a token does NOT free its slot.
	nextTokenID int64
	// mintedTotal counts tokens ever minted; token.TokenCount() counts
	// tokens currently alive. They differ once anything is burned, and the
	// UI wants to show both.
	mintedTotal int64

	// maxPerWallet is a trustless per-wallet cap (0 = unlimited), checked
	// inside Mint. mintedBy tracks lifetime mints per wallet, so the cap
	// can't be reset by burning or transferring away.
	maxPerWallet int64
	mintedBy     *avl.Tree // address.String() -> int64

	// presetURIs is an optional creator-supplied reveal queue; when it is
	// non-empty, MintNext draws the next un-revealed URI instead of
	// trusting whatever URI the minter passes.
	presetURIs []string
	presetNext int

	// onchainTokens / ipfsTokens record where each minted token's artwork
	// actually lives, so the UI can show an honest "fully on-chain" badge
	// instead of trusting the creator's word. Counted at mint time over
	// lifetime mints: burning does not decrement, same as mintedTotal.
	onchainTokens int64
	ipfsTokens    int64

	// generative marks a collection whose artwork is produced by the
	// on-chain nftgen0 engine. Such tokens store only a short seed; the
	// data: URI is rebuilt at read time by TokenURI, which is what makes a
	// generative mint cost gas instead of ~2 GNOT of storage deposit.
	generative bool

	// engine pins the pkgpath of the generator this collection's tokens are
	// rendered by. Set once, when the collection is marked generative, and
	// never rewritten - see package doc, change C.
	engine string

	createdAt int64
}

// CollectionInfo is the read-only, exported view of a Collection.
// Minted is the live (un-burned) count, kept under v1's field name so the
// frontend's existing decoder keeps working; MintedTotal is new.
type CollectionInfo struct {
	ID               string
	Name             string
	Symbol           string
	Description      string
	BaseURI          string
	Creator          address
	MaxSupply        int64
	Minted           int64
	MintedTotal      int64
	PublicMint       bool
	RoyaltyPct       int64
	MaxPerWallet     int64
	PresetsTotal     int64
	PresetsRemaining int64
	CreatedAt        int64
	// New in v4. Appended at the end so existing positional decoders keep
	// working for every field before them.
	OnchainTokens int64
	IpfsTokens    int64
	StorageKind   string
	// New in v5: true when tokens are rendered from an on-chain seed.
	Generative bool
	// New in v5.1: the pinned generative engine pkgpath ("" when the
	// collection is not generative).
	Engine string
}

var (
	collections          = avl.NewTree() // id -> *Collection
	collectionsByCreator = avl.NewTree() // "creator:id" -> id
	ownerIndex           = avl.NewTree() // "owner:collectionId:tokenId" -> true
	collectionTokens     = avl.NewTree() // "collectionId:paddedTokenId" -> tokenId
	attributes           = avl.NewTree() // "collectionId:tokenId" -> []Attribute
	seeds                = avl.NewTree() // "collectionId:tokenId" -> seed string (generative tokens only)
	collCount            int64
)

// callerOf returns the identity this realm authorizes against: the
// immediate caller frame. For a direct wallet call that is the signer;
// for a cross-realm call it is the calling realm's own address, never the
// original signer. See the package doc, change #1.
func callerOf(cur realm) address {
	return cur.Previous().Address()
}

// CreateCollection registers a brand-new GRC-721 collection owned by the
// caller and returns its collection ID. Set publicMint to true to let
// anyone mint into the collection; otherwise only the creator can. Pass
// maxPerWallet = 0 for no per-wallet cap.
func CreateCollection(cur realm, name, symbol, description, baseURI string, maxSupply, royaltyPct, maxPerWallet int64, publicMint bool) string {
	caller := callerOf(cur)

	if name == "" {
		panic("name must not be empty")
	}
	if len(name) > MaxNameLen {
		panic("name too long (max " + strconv.Itoa(MaxNameLen) + " chars)")
	}
	if len(symbol) > MaxSymbolLen {
		panic("symbol too long (max " + strconv.Itoa(MaxSymbolLen) + " chars)")
	}
	if len(description) > MaxDescriptionLen {
		panic("description too long (max " + strconv.Itoa(MaxDescriptionLen) + " chars)")
	}
	if len(baseURI) > MaxURILen {
		panic("baseURI too long")
	}
	if maxSupply <= 0 {
		panic("maxSupply must be positive")
	}
	if maxSupply > MaxCollectionSupply {
		panic("maxSupply must be at most " + strconv.Itoa(MaxCollectionSupply))
	}
	if royaltyPct < 0 || royaltyPct > MaxRoyaltyPercent {
		panic("royaltyPct must be between 0 and " + strconv.Itoa(MaxRoyaltyPercent))
	}
	if maxPerWallet < 0 {
		panic("maxPerWallet must be >= 0 (0 means unlimited)")
	}

	collCount++
	id := strconv.FormatInt(collCount, 10)

	c := &Collection{
		id:           id,
		name:         name,
		symbol:       symbol,
		description:  description,
		baseURI:      baseURI,
		creator:      caller,
		maxSupply:    maxSupply,
		publicMint:   publicMint,
		royaltyPct:   royaltyPct,
		token:        grc721.NewNFTWithRoyalty(0, cur, name, symbol),
		nextTokenID:  1,
		maxPerWallet: maxPerWallet,
		mintedBy:     avl.NewTree(),
		createdAt:    runtime.ChainHeight(),
	}
	collections.Set(id, c)
	collectionsByCreator.Set(caller.String()+":"+id, id)

	chain.Emit(
		"CollectionCreated",
		"id", id,
		"creator", caller.String(),
		"name", name,
		"symbol", symbol,
	)

	return id
}

// Mint mints the next token in a collection to the caller and returns the
// new token ID.
func Mint(cur realm, collectionID, tokenURI string) string {
	assertNotGenerative(collectionID)
	return mint(cur, callerOf(cur), collectionID, tokenURI, "")
}

// MintWithTraits mints like Mint and additionally records on-chain traits.
// traits is a compact "trait=value;trait=value" string because gno.land's
// vm.MsgCall only carries scalar string arguments — the same reason batch
// minting loops single calls instead of passing an array.
// Only the collection's creator may hand-write traits: a stranger minting
// into a public collection must not be able to award themselves
// "Rarity=Legendary" and poison the marketplace filter (package doc,
// change B). Public minters can still mint - they just cannot dictate
// metadata that the market prices.
func MintWithTraits(cur realm, collectionID, tokenURI, traits string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if c.generative {
		panic("this collection is generative; its traits come from the engine - use MintGenerative")
	}
	if traits != "" && caller != c.creator {
		panic("only the collection's creator can set traits by hand; use Mint instead")
	}
	return mint(cur, caller, collectionID, tokenURI, traits)
}

// MintNext draws the next un-revealed URI from the collection's preset
// queue and mints it to the caller, so the minter has no say over which
// artwork they receive.
func MintNext(cur realm, collectionID string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if c.generative {
		panic("this collection is generative; use MintGenerative")
	}
	if len(c.presetURIs) == 0 {
		panic("this collection has no preset artwork queue - mint normally instead")
	}
	if c.presetNext >= len(c.presetURIs) {
		panic("no preset artwork left to reveal - the queue is exhausted")
	}
	uri := c.presetURIs[c.presetNext]
	c.presetNext++
	return mint(cur, caller, collectionID, uri, "")
}

func mint(cur realm, caller address, collectionID, tokenURI, traits string) string {
	c := mustGetCollection(collectionID)

	if !c.publicMint && caller != c.creator {
		panic("minting into this collection is restricted to its creator")
	}
	// Supply gate on the ID counter, not the live count: burning must not
	// re-open a slot (see package doc, change #2).
	if c.nextTokenID > c.maxSupply {
		panic("collection has reached its max supply")
	}
	if len(tokenURI) > MaxURILen {
		panic("tokenURI too long")
	}

	// Trustless per-wallet cap, counted over lifetime mints so it survives
	// burning and transferring away (see package doc, change #3).
	if c.maxPerWallet > 0 {
		if mintedByWallet(c, caller) >= c.maxPerWallet {
			panic("wallet has reached this collection's per-wallet mint limit of " +
				strconv.FormatInt(c.maxPerWallet, 10))
		}
	}

	attrs := parseTraits(traits)

	tidStr := strconv.FormatInt(c.nextTokenID, 10)
	c.nextTokenID++
	c.mintedTotal++
	tid := grc721.TokenID(tidStr)

	if err := c.token.Mint(caller, tid); err != nil {
		panic(err)
	}
	if tokenURI != "" {
		if _, err := c.token.SetTokenURI(caller, tid, grc721.TokenURI(tokenURI)); err != nil {
			panic(err)
		}
	}
	if c.royaltyPct > 0 {
		// Freshly minted tokens are owned by caller, so caller satisfies
		// SetTokenRoyalty's "caller must be current owner" check.
		if err := c.token.SetTokenRoyalty(caller, tid, grc721.RoyaltyInfo{
			PaymentAddress: c.creator,
			Percentage:     c.royaltyPct,
		}); err != nil {
			panic(err)
		}
	}

	// Where does this token's artwork live? A token with no URI of its own
	// inherits the collection's baseURI, so classify whichever one applies.
	effURI := tokenURI
	if effURI == "" {
		effURI = c.baseURI
	}
	if strings.HasPrefix(effURI, "data:") {
		c.onchainTokens++
	} else if strings.HasPrefix(effURI, "ipfs://") {
		c.ipfsTokens++
	}

	c.mintedBy.Set(caller.String(), mintedByWallet(c, caller)+1)
	ownerIndex.Set(caller.String()+":"+collectionID+":"+tidStr, true)
	collectionTokens.Set(collectionID+":"+padID(tidStr), tidStr)
	if len(attrs) > 0 {
		attributes.Set(collectionID+":"+tidStr, attrs)
	}

	chain.Emit(
		"NFTMinted",
		"collection", collectionID,
		"tokenId", tidStr,
		"to", caller.String(),
	)

	return tidStr
}

// SetGenerative marks (or unmarks) a collection as generative, meaning
// its tokens are minted with MintGenerative and rendered from a seed by
// the on-chain nftgen0 engine. Creator-only, and refused once anything
// has been minted so a collection can never change what its existing
// tokens look like.
func SetGenerative(cur realm, collectionID string, generative bool) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can change its generative mode")
	}
	if c.mintedTotal > 0 {
		panic("collection already has minted tokens; generative mode is fixed")
	}
	c.generative = generative
	if generative {
		c.engine = Engine
	} else {
		c.engine = ""
	}
}

// MintGenerative mints the next token of a generative collection to the
// caller. No artwork is stored: the token keeps a seed, and its traits
// are the ones nftgen0 derives from that same seed, so the trait filter
// in the marketplace keeps working exactly as it does for stored art.
func MintGenerative(cur realm, collectionID string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if !c.generative {
		panic("this collection is not generative; use Mint or MintNext instead")
	}

	seed := nftgen0.SeedFor(collectionID, strconv.FormatInt(c.nextTokenID, 10))
	// The traits are NOT written to the attributes tree: they are a pure
	// function of this seed and TokenAttributes derives them on read. v5
	// stored both and paid 12-20 KB of deposit per token for the privilege
	// (package doc, change A).
	tidStr := mint(cur, caller, collectionID, "", "")

	seeds.Set(collectionID+":"+tidStr, seed)
	// The artwork is produced and served entirely by on-chain code, so it
	// is on-chain in the strongest sense - there is not even a stored blob
	// that could rot. mint() classifies by URI and a generative mint has
	// none, so it only counted this token if the collection's baseURI is
	// itself a data: URI; guard against counting it twice.
	if !strings.HasPrefix(c.baseURI, "data:") {
		c.onchainTokens++
	}

	chain.Emit(
		"GenerativeMinted",
		"collection", collectionID,
		"tokenId", tidStr,
		"seed", seed,
		"to", caller.String(),
	)

	return tidStr
}

// QueuePresetURI appends one tokenURI to a collection's reveal queue.
// Creator-only.
func QueuePresetURI(cur realm, collectionID, uri string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can queue preset artwork")
	}
	if uri == "" {
		panic("uri must not be empty")
	}
	if len(uri) > MaxURILen {
		panic("uri too long")
	}
	if int64(len(c.presetURIs)) >= c.maxSupply {
		panic("preset queue is already as large as the collection's max supply")
	}
	c.presetURIs = append(c.presetURIs, uri)
}

// SetMaxPerWallet sets (0 clears) the trustless per-wallet mint cap.
// Creator-only. Lowering it never retroactively invalidates existing
// tokens; it only blocks further mints by wallets already at or over it.
func SetMaxPerWallet(cur realm, collectionID string, max int64) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can set its mint limit")
	}
	if max < 0 {
		panic("max must be >= 0 (0 clears the limit)")
	}
	c.maxPerWallet = max
}

// Approve approves `to` to transfer a single token on the caller's behalf.
func Approve(cur realm, collectionID, tokenID string, to address) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if err := c.token.Approve(caller, to, grc721.TokenID(tokenID)); err != nil {
		panic(err)
	}
}

// SetApprovalForAll grants/revokes operator permission across all of the
// caller's tokens in one collection (e.g. approving the marketplace realm
// once instead of per-token).
func SetApprovalForAll(cur realm, collectionID string, operator address, approved bool) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if err := c.token.SetApprovalForAll(caller, operator, approved); err != nil {
		panic(err)
	}
}

// TransferFrom transfers a token from `from` to `to`. The caller must be
// the owner or an approved operator/spender — which is how nftmarket2 and
// nftoffers2 move tokens: they call this via cross(cur), so the caller
// seen here is the marketplace realm's own address, exactly the identity
// the seller approved.
func TransferFrom(cur realm, collectionID, tokenID string, from, to address) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	tid := grc721.TokenID(tokenID)

	if err := c.token.TransferFrom(caller, from, to, tid); err != nil {
		panic(err)
	}

	ownerIndex.Remove(from.String() + ":" + collectionID + ":" + tokenID)
	ownerIndex.Set(to.String()+":"+collectionID+":"+tokenID, true)

	chain.Emit(
		"Transfer",
		"collection", collectionID,
		"tokenId", tokenID,
		"from", from.String(),
		"to", to.String(),
	)
}

// Burn destroys a token. Caller must be the token's current owner. The
// burned token's supply slot is never reused.
func Burn(cur realm, collectionID, tokenID string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	tid := grc721.TokenID(tokenID)

	owner, err := c.token.OwnerOf(tid)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token owner can burn it")
	}
	if err := c.token.Burn(tid); err != nil {
		panic(err)
	}

	ownerIndex.Remove(owner.String() + ":" + collectionID + ":" + tokenID)
	collectionTokens.Remove(collectionID + ":" + padID(tokenID))
	attributes.Remove(collectionID + ":" + tokenID)
	seeds.Remove(collectionID + ":" + tokenID)

	chain.Emit("Burn", "collection", collectionID, "tokenId", tokenID, "from", owner.String())
}

// Read-only views.

// GetCollection returns the exported view of one collection.
func GetCollection(collectionID string) CollectionInfo {
	return toInfo(mustGetCollection(collectionID))
}

// ListCollections returns up to `limit` collections starting at `offset`,
// ordered by collection ID (creation order).
func ListCollections(offset, limit int64) []CollectionInfo {
	out := make([]CollectionInfo, 0, limit)
	collections.IterateByOffset(int(offset), int(limit), func(key string, value any) bool {
		out = append(out, toInfo(value.(*Collection)))
		return false
	})
	return out
}

// CollectionCount returns the total number of collections ever created.
func CollectionCount() int64 {
	return collCount
}

// TokensOfOwner returns "collectionId:tokenId" pairs for every token the
// given address owns, across every collection in this realm.
func TokensOfOwner(owner address) []string {
	var out []string
	prefix := owner.String() + ":"
	ownerIndex.Iterate(prefix, owner.String()+";", func(key string, value any) bool {
		out = append(out, key[len(prefix):])
		return false
	})
	return out
}

// TokensOfCollection returns the live token IDs of one collection in
// ascending numeric order. v1 had no such view at all — the frontend had
// to probe OwnerOf(1..maxSupply) one RPC call at a time.
func TokensOfCollection(collectionID string, offset, limit int64) []string {
	mustGetCollection(collectionID)
	var out []string
	var seen int64
	prefix := collectionID + ":"
	collectionTokens.Iterate(prefix, collectionID+";", func(key string, value any) bool {
		if seen < offset {
			seen++
			return false
		}
		if limit > 0 && int64(len(out)) >= limit {
			return true
		}
		out = append(out, value.(string))
		seen++
		return false
	})
	return out
}

// MintedByWallet returns how many tokens of a collection an address has
// minted over its lifetime (the number the per-wallet cap is checked
// against — not the same as the current balance).
func MintedByWallet(collectionID string, wallet address) int64 {
	return mintedByWallet(mustGetCollection(collectionID), wallet)
}

// BalanceOf returns how many tokens of one collection an address owns.
func BalanceOf(collectionID string, owner address) int64 {
	bal, err := mustGetCollection(collectionID).token.BalanceOf(owner)
	if err != nil {
		panic(err)
	}
	return bal
}

// OwnerOf returns the current owner of a token.
func OwnerOf(collectionID, tokenID string) (address, error) {
	return mustGetCollection(collectionID).token.OwnerOf(grc721.TokenID(tokenID))
}

// TokenURI returns the metadata URI of a token.
//
// For a generative token nothing is stored but a short seed: the data:
// URI is rebuilt here by the nftgen0 engine on every read. Storing a
// 4-5 KB base64 SVG per token cost roughly 2.1 GNOT of storage deposit
// in v4; a seed costs a few dozen bytes, and because the generator is
// deterministic the artwork is byte-identical forever.
func TokenURI(collectionID, tokenID string) (string, error) {
	if seed, ok := seeds.Get(collectionID + ":" + tokenID).(string); ok {
		return nftgen0.DataURI(seed), nil
	}
	return mustGetCollection(collectionID).token.TokenURI(grc721.TokenID(tokenID))
}

// TokenSeed returns the generative seed of a token, or "" when the token
// stores an ordinary URI.
func TokenSeed(collectionID, tokenID string) string {
	if seed, ok := seeds.Get(collectionID + ":" + tokenID).(string); ok {
		return seed
	}
	return ""
}

// TokenAttributes returns a token's traits.
//
// Stored traits win when they exist, so tokens minted with explicit traits
// (and any token carried over from an older realm) keep behaving exactly as
// before. A generative token has none: its traits are rebuilt here from its
// seed, which is both cheaper and unforgeable - see package doc, changes A
// and B. The output is byte-identical to what v5 used to persist, which the
// realm's test suite asserts seed by seed.
func TokenAttributes(collectionID, tokenID string) []Attribute {
	if v := attributes.Get(collectionID + ":" + tokenID); v != nil {
		return v.([]Attribute)
	}
	if seed, ok := seeds.Get(collectionID + ":" + tokenID).(string); ok {
		return deriveAttributes(seed)
	}
	return nil
}

// deriveAttributes rebuilds the trait list for a seed. It mirrors
// nftgen0.TraitString field for field; the test suite pins that equality so
// the two can never drift apart silently.
func deriveAttributes(seed string) []Attribute {
	tr := nftgen0.TraitsOf(seed)
	aura := "No"
	if tr.Aura {
		aura = "Yes"
	}
	return []Attribute{
		{TraitType: "Palette", Value: tr.Palette},
		{TraitType: "Shape", Value: tr.Shape},
		{TraitType: "Ground", Value: tr.Ground},
		{TraitType: "Elements", Value: strconv.Itoa(tr.Elements)},
		{TraitType: "Symmetry", Value: strconv.Itoa(tr.Symmetry)},
		{TraitType: "Aura", Value: aura},
		{TraitType: "Rarity", Value: tr.Rarity},
	}
}

// TokenMetadata assembles a complete metadata JSON document for a token
// inside the realm, so a fully on-chain token needs no IPFS, no gateway
// and no pinning service to be readable.
func TokenMetadata(collectionID, tokenID string) string {
	c := mustGetCollection(collectionID)
	uri, err := TokenURI(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	_ = c

	out := "{\"name\":\"" + jsonEscape(c.name+" #"+tokenID) + "\""
	out += ",\"description\":\"" + jsonEscape(c.description) + "\""
	out += ",\"image\":\"" + jsonEscape(uri) + "\""
	out += ",\"attributes\":["
	for i, a := range TokenAttributes(collectionID, tokenID) {
		if i > 0 {
			out += ","
		}
		out += "{\"trait_type\":\"" + jsonEscape(a.TraitType) +
			"\",\"value\":\"" + jsonEscape(a.Value) + "\"}"
	}
	out += "]}"
	return out
}

// GetApproved returns the address approved for a single token, if any.
func GetApproved(collectionID, tokenID string) (address, error) {
	return mustGetCollection(collectionID).token.GetApproved(grc721.TokenID(tokenID))
}

// IsApprovedForAll reports whether operator can manage all of owner's
// tokens in one collection.
func IsApprovedForAll(collectionID string, owner, operator address) bool {
	return mustGetCollection(collectionID).token.IsApprovedForAll(owner, operator)
}

// RoyaltyInfo returns the payment address and royalty amount owed for a
// sale of the given token at salePrice.
func RoyaltyInfo(collectionID, tokenID string, salePrice int64) (address, int64, error) {
	return mustGetCollection(collectionID).token.RoyaltyInfo(grc721.TokenID(tokenID), salePrice)
}

// Render implements the gno.land realm home-page convention so the
// factory is browsable from gnoweb even without the dedicated frontend.
func Render(path string) string {
	if path != "" {
		v := collections.Get(path)
		if v == nil {
			return "# 404\n\ncollection not found: " + path
		}
		return renderCollection(v.(*Collection))
	}

	out := ufmt.Sprintf("# gnoNFT Factory v5.2\n\n%d collection(s)\n\n", collCount)
	collections.Iterate("", "", func(key string, value any) bool {
		c := value.(*Collection)
		out += ufmt.Sprintf(
			"- [#%s %s (%s)](:%s) - %d/%d minted, by %s\n",
			c.id, c.name, c.symbol, c.id, c.mintedTotal, c.maxSupply, c.creator.String(),
		)
		return false
	})
	return out
}

func renderCollection(c *Collection) string {
	out := ufmt.Sprintf("# %s (%s)\n\n%s\n\n", c.name, c.symbol, c.description)
	out += ufmt.Sprintf("- Creator: %s\n", c.creator.String())
	out += ufmt.Sprintf("- Minted: %d / %d\n", c.mintedTotal, c.maxSupply)
	out += ufmt.Sprintf("- Currently live: %d\n", c.token.TokenCount())
	out += ufmt.Sprintf("- Public mint: %t\n", c.publicMint)
	out += ufmt.Sprintf("- Royalty: %d%%\n", c.royaltyPct)
	if c.maxPerWallet > 0 {
		out += ufmt.Sprintf("- Max per wallet: %d\n", c.maxPerWallet)
	}
	if total := len(c.presetURIs); total > 0 {
		out += ufmt.Sprintf("- Presets revealed: %d / %d\n", c.presetNext, total)
	}
	return out
}

// Internal helpers.

func mintedByWallet(c *Collection, wallet address) int64 {
	v := c.mintedBy.Get(wallet.String())
	if v == nil {
		return 0
	}
	return v.(int64)
}

// parseTraits turns "Background=Blue;Eyes=Laser" into attributes. Empty
// segments are skipped; a segment with no '=' is rejected outright rather
// than silently stored, so a typo can't be minted into a token forever.
func parseTraits(traits string) []Attribute {
	if traits == "" {
		return nil
	}
	var out []Attribute
	for _, seg := range strings.Split(traits, ";") {
		seg = strings.TrimSpace(seg)
		if seg == "" {
			continue
		}
		idx := strings.Index(seg, "=")
		if idx <= 0 || idx == len(seg)-1 {
			panic("malformed trait \"" + seg + "\": expected trait=value pairs separated by ';'")
		}
		k := strings.TrimSpace(seg[:idx])
		v := strings.TrimSpace(seg[idx+1:])
		if len(k) > MaxTraitLen || len(v) > MaxTraitLen {
			panic("trait name/value too long (max " + strconv.Itoa(MaxTraitLen) + " chars)")
		}
		out = append(out, Attribute{TraitType: k, Value: v})
		if len(out) > MaxAttributesPerToken {
			panic("too many traits (max " + strconv.Itoa(MaxAttributesPerToken) + ")")
		}
	}
	return out
}

// padID zero-pads a numeric token ID so the collectionTokens tree sorts
// numerically rather than lexicographically ("10" must come after "2").
func padID(id string) string {
	const width = 12
	if len(id) >= width {
		return id
	}
	return "000000000000"[:width-len(id)] + id
}

func jsonEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

func toInfo(c *Collection) CollectionInfo {
	presetsTotal := int64(len(c.presetURIs))
	remaining := presetsTotal - int64(c.presetNext)
	if remaining < 0 {
		remaining = 0
	}
	return CollectionInfo{
		ID:               c.id,
		Name:             c.name,
		Symbol:           c.symbol,
		Description:      c.description,
		BaseURI:          c.baseURI,
		Creator:          c.creator,
		MaxSupply:        c.maxSupply,
		Minted:           c.token.TokenCount(),
		MintedTotal:      c.mintedTotal,
		PublicMint:       c.publicMint,
		RoyaltyPct:       c.royaltyPct,
		MaxPerWallet:     c.maxPerWallet,
		PresetsTotal:     presetsTotal,
		PresetsRemaining: remaining,
		CreatedAt:        c.createdAt,
		OnchainTokens:    c.onchainTokens,
		IpfsTokens:       c.ipfsTokens,
		StorageKind:      storageKind(c),
		Generative:       c.generative,
		Engine:           c.engine,
	}
}

// storageKind reports where a collection's artwork lives:
//
//	"onchain"  every minted token is a data: URI - nothing off-chain to rot
//	"ipfs"     every minted token points at ipfs://
//	"external" plain http(s) links
//	"mixed"    a bit of both
//	"unknown"  nothing minted yet and no baseURI hint
//
// Before the first mint the baseURI is the only evidence available, so it
// is used as the hint; after that the per-token counters decide.
func storageKind(c *Collection) string {
	if c.mintedTotal == 0 {
		if strings.HasPrefix(c.baseURI, "data:") {
			return "onchain"
		}
		if strings.HasPrefix(c.baseURI, "ipfs://") {
			return "ipfs"
		}
		if c.baseURI == "" {
			return "unknown"
		}
		return "external"
	}
	if c.onchainTokens == c.mintedTotal {
		return "onchain"
	}
	if c.ipfsTokens == c.mintedTotal {
		return "ipfs"
	}
	if c.onchainTokens == 0 && c.ipfsTokens == 0 {
		return "external"
	}
	return "mixed"
}

// CollectionStorageKind exposes storageKind as a standalone view so the UI
// can badge a collection without decoding a whole CollectionInfo.
func CollectionStorageKind(collectionID string) string {
	return storageKind(mustGetCollection(collectionID))
}

// assertNotGenerative refuses hand-minting into a generative collection, so
// "every token here is derived from its seed" stays a checkable claim.
func assertNotGenerative(collectionID string) {
	if mustGetCollection(collectionID).generative {
		panic("this collection is generative; use MintGenerative")
	}
}

func mustGetCollection(id string) *Collection {
	v := collections.Get(id)
	if v == nil {
		panic("collection not found: " + id)
	}
	return v.(*Collection)
}

// Hardened, multi-source, batch-capable migration into this realm.
//
// WHAT V5.3 ADDS OVER V5.2's migrate52.gno
//
//  1. TWO accepted sources instead of one (nft51 AND nft52), so a holder who
//     skipped a version never has to claim twice through an intermediate
//     realm. Both are consts: the accepted set can never be repointed, and a
//     future realm that accepts more sources is a different pkgpath the user
//     explicitly opts into.
//  2. Batch claiming. ClaimMigratedBatch takes a comma-separated token list
//     (vm.MsgCall only carries scalar strings) and claims up to
//     MaxClaimBatch tokens in one transaction, so a wallet holding N tokens
//     pays one fixed transaction cost instead of N.
//  3. Claim marker is written BEFORE the cross-realm calls. Even if a future
//     source realm were re-entrant, a token can never be claimed twice.
//  4. Permissionless collection registration. In v5.2 only the original
//     creator could register a collection, so an absent creator could strand
//     their holders. Here ANY holder of a token in the source collection can
//     register it - which is safe because every field (name, symbol,
//     description, baseURI, creator, maxSupply, royalty, generative, engine)
//     is copied verbatim from the source realm's own state. A stranger
//     registering the collection cannot alter one byte of it, cannot become
//     its creator, and cannot redirect its royalties.
//  5. Approval hygiene helpers. SourceApprovalOf lets the UI show, and nag
//     about, a still-open SetApprovalForAll after a batch claim. A realm
//     cannot revoke a user's approval on the user's behalf (that signature
//     belongs to the owner), so the safe pattern is surfaced instead of
//     silently left open.
//
// STILL TRUE, BY DESIGN: no admin, no pause, no proxy, no key. A collection
// is registered from chain-derived data only, a token is moved only by its
// own current owner, the old token is burned in the same transaction, and
// nobody is ever forced to migrate.
package nft53

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/tokens/grc721"
	"gno.land/p/nt/avl/v0"

	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft51"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft52"
)

// Accepted source realms. Callers pass the short label; the pkgpath consts
// exist so the label can be resolved to an auditable path in views.
const (
	SourceV51 = "v5.1"
	SourceV52 = "v5.2"

	SourceRealmV51 = "gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft51"
	SourceRealmV52 = "gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft52"

	// MaxClaimBatch bounds one batch so a caller cannot build a transaction
	// that is guaranteed to run out of gas after doing partial work. The
	// whole batch is one transaction: it either all applies or all reverts.
	MaxClaimBatch = 25
)

var (
	// migratedTo maps "source:oldCollectionID" -> this realm's collection ID.
	migratedTo = avl.NewTree()
	// migratedFrom is the reverse map for the "migrated from" badge.
	migratedFrom = avl.NewTree()
	// claimedFrom marks "source:oldCollectionID:tokenID" as claimed.
	claimedFrom = avl.NewTree()
)

// srcCollection is the source-realm-agnostic view of a collection, so the
// migration logic is written once for both accepted sources.
type srcCollection struct {
	name        string
	symbol      string
	description string
	baseURI     string
	creator     address
	maxSupply   int64
	mintedTotal int64
	royaltyPct  int64
	maxPerWallet int64
	publicMint  bool
	generative  bool
	engine      string
}

func assertSource(source string) {
	if source != SourceV51 && source != SourceV52 {
		panic("unknown source realm; use \"" + SourceV51 + "\" or \"" + SourceV52 + "\"")
	}
}

// SourceRealmPath resolves a source label to the pkgpath it will act on, so
// a caller can verify what they are about to touch before signing.
func SourceRealmPath(source string) string {
	assertSource(source)
	if source == SourceV51 {
		return SourceRealmV51
	}
	return SourceRealmV52
}

func srcGetCollection(source, collectionID string) srcCollection {
	assertSource(source)
	if source == SourceV51 {
		i := nft51.GetCollection(collectionID)
		return srcCollection{
			name: i.Name, symbol: i.Symbol, description: i.Description,
			baseURI: i.BaseURI, creator: i.Creator, maxSupply: i.MaxSupply,
			mintedTotal: i.MintedTotal, royaltyPct: i.RoyaltyPct,
			maxPerWallet: i.MaxPerWallet, publicMint: i.PublicMint,
			generative: i.Generative, engine: i.Engine,
		}
	}
	i := nft52.GetCollection(collectionID)
	return srcCollection{
		name: i.Name, symbol: i.Symbol, description: i.Description,
		baseURI: i.BaseURI, creator: i.Creator, maxSupply: i.MaxSupply,
		mintedTotal: i.MintedTotal, royaltyPct: i.RoyaltyPct,
		maxPerWallet: i.MaxPerWallet, publicMint: i.PublicMint,
		generative: i.Generative, engine: i.Engine,
	}
}

func srcOwnerOf(source, collectionID, tokenID string) address {
	assertSource(source)
	if source == SourceV51 {
		owner, err := nft51.OwnerOf(collectionID, tokenID)
		if err != nil {
			panic(err)
		}
		return owner
	}
	owner, err := nft52.OwnerOf(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	return owner
}

func srcIsApproved(source, collectionID, tokenID string, owner, spender address) bool {
	assertSource(source)
	if source == SourceV51 {
		approved, _ := nft51.GetApproved(collectionID, tokenID)
		return approved == spender || nft51.IsApprovedForAll(collectionID, owner, spender)
	}
	approved, _ := nft52.GetApproved(collectionID, tokenID)
	return approved == spender || nft52.IsApprovedForAll(collectionID, owner, spender)
}

func srcSeed(source, collectionID, tokenID string) string {
	assertSource(source)
	if source == SourceV51 {
		return nft51.TokenSeed(collectionID, tokenID)
	}
	return nft52.TokenSeed(collectionID, tokenID)
}

func srcTokenURI(source, collectionID, tokenID string) string {
	assertSource(source)
	if source == SourceV51 {
		if u, err := nft51.TokenURI(collectionID, tokenID); err == nil {
			return u
		}
		return ""
	}
	if u, err := nft52.TokenURI(collectionID, tokenID); err == nil {
		return u
	}
	return ""
}

func srcAttributes(source, collectionID, tokenID string) []Attribute {
	assertSource(source)
	var out []Attribute
	if source == SourceV51 {
		for _, a := range nft51.TokenAttributes(collectionID, tokenID) {
			out = append(out, Attribute{TraitType: a.TraitType, Value: a.Value})
		}
		return out
	}
	for _, a := range nft52.TokenAttributes(collectionID, tokenID) {
		out = append(out, Attribute{TraitType: a.TraitType, Value: a.Value})
	}
	return out
}

// srcPullAndBurn moves the source token to this realm and destroys it. Both
// steps happen inside the caller's transaction, so the token can never be
// alive in two realms at once.
func srcPullAndBurn(cur realm, source, collectionID, tokenID string, from, to address) {
	assertSource(source)
	if source == SourceV51 {
		nft51.TransferFrom(cross(cur), collectionID, tokenID, from, to)
		nft51.Burn(cross(cur), collectionID, tokenID)
		return
	}
	nft52.TransferFrom(cross(cur), collectionID, tokenID, from, to)
	nft52.Burn(cross(cur), collectionID, tokenID)
}

// SourceApprovalOf reports whether `spender` may currently move one source
// token. The UI uses it with this realm's own address to nag the user into
// revoking a blanket SetApprovalForAll once their migration is finished: a
// realm cannot revoke an approval the owner signed, so the honest move is to
// make the leftover permission visible.
func SourceApprovalOf(source, collectionID, tokenID string, owner, spender address) bool {
	return srcIsApproved(source, collectionID, tokenID, owner, spender)
}

// MigrateCollection registers a source collection in this realm and returns
// the new collection ID.
//
// Callable by the original creator OR by any current holder of a token in
// that source collection. That is deliberately permissionless: every field
// is copied from the source realm's own state, including the creator address
// and the royalty percentage, so whoever pays the registration fee cannot
// change the collection, cannot claim its creator seat and cannot redirect
// its royalties. It only removes the risk of an inactive creator stranding
// their holders.
func MigrateCollection(cur realm, source, oldCollectionID string) string {
	caller := callerOf(cur)
	assertSource(source)

	key := source + ":" + oldCollectionID
	if _, ok := migratedTo.Get(key).(string); ok {
		panic("this collection has already been migrated")
	}

	info := srcGetCollection(source, oldCollectionID)
	if caller != info.creator && !callerHoldsAnyToken(source, oldCollectionID, caller) {
		panic("only the collection's creator or one of its token holders can migrate it")
	}

	collCount++
	id := strconv.FormatInt(collCount, 10)

	c := &Collection{
		id:          id,
		name:        info.name,
		symbol:      info.symbol,
		description: info.description,
		baseURI:     info.baseURI,
		// The ORIGINAL creator, never the caller: royalties and creator-only
		// powers stay exactly where they were.
		creator:    info.creator,
		maxSupply:  info.maxSupply,
		publicMint: info.publicMint,
		royaltyPct: info.royaltyPct,
		token:      grc721.NewNFTWithRoyalty(0, cur, info.name, info.symbol),
		// Reserve the source's ID range so a claim and a fresh mint can never
		// compete for the same token ID.
		nextTokenID:  info.mintedTotal + 1,
		maxPerWallet: info.maxPerWallet,
		mintedBy:     avl.NewTree(),
		generative:   info.generative,
		engine:       info.engine,
		createdAt:    runtime.ChainHeight(),
	}
	collections.Set(id, c)
	collectionsByCreator.Set(info.creator.String()+":"+id, id)
	migratedTo.Set(key, id)
	migratedFrom.Set(id, key)

	chain.Emit(
		"CollectionMigrated",
		"source", SourceRealmPath(source),
		"oldCollection", oldCollectionID,
		"id", id,
		"creator", info.creator.String(),
		"registeredBy", caller.String(),
	)

	return id
}

// callerHoldsAnyToken checks whether caller owns at least one live token of
// the source collection, bounded by the source's lifetime mint count.
func callerHoldsAnyToken(source, collectionID string, caller address) bool {
	info := srcGetCollection(source, collectionID)
	for i := int64(1); i <= info.mintedTotal; i++ {
		tokenID := strconv.FormatInt(i, 10)
		if ownerOfOrEmpty(source, collectionID, tokenID) == caller {
			return true
		}
	}
	return false
}

// ownerOfOrEmpty is srcOwnerOf without the panic, for burned/missing tokens.
func ownerOfOrEmpty(source, collectionID, tokenID string) address {
	if source == SourceV51 {
		owner, err := nft51.OwnerOf(collectionID, tokenID)
		if err != nil {
			return address("")
		}
		return owner
	}
	owner, err := nft52.OwnerOf(collectionID, tokenID)
	if err != nil {
		return address("")
	}
	return owner
}

// ClaimMigrated moves one token from an accepted source realm into this one,
// keeping its ID, seed or URI, traits, royalty and creator. The caller must
// own the token in the source realm and must have approved THIS realm's
// address there first.
func ClaimMigrated(cur realm, source, oldCollectionID, tokenID string) string {
	return claimOne(cur, source, oldCollectionID, strings.TrimSpace(tokenID), callerOf(cur), cur.Address())
}

// ClaimMigratedBatch claims several tokens of one source collection in a
// single transaction. tokenIDs is a comma-separated list ("1,2,7") because
// vm.MsgCall only carries scalar strings. Up to MaxClaimBatch entries; the
// batch is atomic, so one bad entry reverts the whole call and nothing is
// half-migrated.
func ClaimMigratedBatch(cur realm, source, oldCollectionID, tokenIDs string) int64 {
	caller := callerOf(cur)
	self := cur.Address()

	parts := strings.Split(tokenIDs, ",")
	if len(parts) == 0 {
		panic("tokenIDs must not be empty")
	}
	if len(parts) > MaxClaimBatch {
		panic("too many tokens in one batch (max " + strconv.Itoa(MaxClaimBatch) + "); split the claim")
	}

	var n int64
	for _, raw := range parts {
		tokenID := strings.TrimSpace(raw)
		if tokenID == "" {
			panic("tokenIDs contains an empty entry")
		}
		claimOne(cur, source, oldCollectionID, tokenID, caller, self)
		n++
	}

	chain.Emit(
		"BatchMigrated",
		"source", SourceRealmPath(source),
		"oldCollection", oldCollectionID,
		"count", strconv.FormatInt(n, 10),
		"owner", caller.String(),
	)

	return n
}

func claimOne(cur realm, source, oldCollectionID, tokenID string, caller, self address) string {
	assertSource(source)

	newID, ok := migratedTo.Get(source + ":" + oldCollectionID).(string)
	if !ok {
		panic("this collection has not been migrated yet; call MigrateCollection first")
	}
	claimKey := source + ":" + oldCollectionID + ":" + tokenID
	if _, done := claimedFrom.Get(claimKey).(string); done {
		panic("this token has already been claimed")
	}

	owner := srcOwnerOf(source, oldCollectionID, tokenID)
	if owner != caller {
		panic("only the token's current owner can claim it")
	}
	if !srcIsApproved(source, oldCollectionID, tokenID, owner, self) {
		panic("this realm is not approved to move that token yet; approve it in the source realm first")
	}

	// Copy everything that defines the token before destroying it.
	seed := srcSeed(source, oldCollectionID, tokenID)
	uri := ""
	var attrs []Attribute
	if seed == "" {
		uri = srcTokenURI(source, oldCollectionID, tokenID)
		attrs = srcAttributes(source, oldCollectionID, tokenID)
	}

	// Mark the claim BEFORE any cross-realm call: a re-entrant source realm
	// must not be able to walk back into claimOne for the same token.
	claimedFrom.Set(claimKey, newID+":"+tokenID)

	srcPullAndBurn(cur, source, oldCollectionID, tokenID, caller, self)

	c := mustGetCollection(newID)
	tid := grc721.TokenID(tokenID)
	if err := c.token.Mint(caller, tid); err != nil {
		panic(err)
	}
	if uri != "" {
		if _, err := c.token.SetTokenURI(caller, tid, grc721.TokenURI(uri)); err != nil {
			panic(err)
		}
	}
	if c.royaltyPct > 0 {
		if err := c.token.SetTokenRoyalty(caller, tid, grc721.RoyaltyInfo{
			PaymentAddress: c.creator,
			Percentage:     c.royaltyPct,
		}); err != nil {
			panic(err)
		}
	}

	c.mintedTotal++
	ownerIndex.Set(caller.String()+":"+newID+":"+tokenID, true)
	collectionTokens.Set(newID+":"+padID(tokenID), tokenID)
	if seed != "" {
		seeds.Set(newID+":"+tokenID, seed)
		if !strings.HasPrefix(c.baseURI, "data:") {
			c.onchainTokens++
		}
	} else {
		if len(attrs) > 0 {
			attributes.Set(newID+":"+tokenID, attrs)
		}
		effURI := uri
		if effURI == "" {
			effURI = c.baseURI
		}
		if strings.HasPrefix(effURI, "data:") {
			c.onchainTokens++
		} else if strings.HasPrefix(effURI, "ipfs://") {
			c.ipfsTokens++
		}
	}

	chain.Emit(
		"TokenMigrated",
		"source", SourceRealmPath(source),
		"oldCollection", oldCollectionID,
		"collection", newID,
		"tokenId", tokenID,
		"owner", caller.String(),
	)

	return tokenID
}

// Read-only migration views.

// MigratedCollectionOf returns this realm's collection ID for a source
// collection, or "" when it has not been migrated.
func MigratedCollectionOf(source, oldCollectionID string) string {
	id, _ := migratedTo.Get(source + ":" + oldCollectionID).(string)
	return id
}

// SourceCollectionOf returns "source:oldCollectionID" for a collection that
// arrived by migration, or "" when it was created here.
func SourceCollectionOf(collectionID string) string {
	old, _ := migratedFrom.Get(collectionID).(string)
	return old
}

// ClaimedAs returns "collectionId:tokenId" in this realm for an already
// claimed source token, or "" when it has not been claimed.
func ClaimedAs(source, oldCollectionID, tokenID string) string {
	ref, _ := claimedFrom.Get(source + ":" + oldCollectionID + ":" + tokenID).(string)
	return ref
}

// Package nft53 is the v5.3 GRC-721 NFT factory realm for gnoNFT.
//
// WHAT CHANGED VS V5 (all three are security or cost fixes, no new features)
//
//  A. Generative traits are DERIVED, not stored. v5 wrote the seed AND the
//     seven traits nftgen0 derives from that same seed, so every generative
//     mint paid ~12-20 KB of storage deposit (1.5-2.3 GNOT measured on
//     pearl-1) to persist data that is a pure function of a string the realm
//     already keeps. Here MintGenerative stores only the seed and
//     TokenAttributes rebuilds the traits at read time. Reads are free
//     qevals and nftgen0 is a fixed-cost pure function, so this is a strict
//     cost win with no new gas surface.
//
//  B. Trait spoofing is closed. v5.mint() stored whatever trait string the
//     CALLER supplied and only gated on publicMint, so in any public-mint
//     collection a stranger could mint themselves a token carrying
//     "Rarity=Legendary" and poison the marketplace rarity filter. In v5.1
//     only the collection creator may supply traits by hand; everyone else
//     mints traitless tokens or, in a generative collection, tokens whose
//     traits are the deterministic output of the engine. Rarity therefore
//     cannot be forged by anyone, creator included, in a generative
//     collection.
//
//  C. The rendering engine is PINNED per collection. Derived traits mean a
//     token's appearance now depends on live code rather than a stored blob,
//     so a collection records which engine realm it was created against
//     (Engine in CollectionInfo) at the moment it is marked generative.
//     gno.land realms are immutable, so a pinned engine can never change
//     under an existing token; a future nftgen1 is a different pkgpath and
//     therefore a different, explicitly recorded engine.
//
// Additionally a generative collection now refuses Mint / MintWithTraits /
// MintNext outright: mixing hand-written art or hand-written traits into a
// collection that advertises "every token is derived from its seed" would
// make that promise unverifiable.
//
// MIGRATION POLICY (why old tokens are safe when v6 arrives)
//
// Realms are immutable, so a fix always means a new pkgpath, and the
// project treats that as a first-class event rather than an accident:
// every piece of state a successor realm needs in order to reproduce a
// token exactly - seed, traits, URI, creator, royalty, per-collection
// config - is exposed here as a pure public read (GetCollection,
// TokenSeed, TokenAttributes, TokenURI, TokenMetadata, OwnerOf,
// RoyaltyInfo, TokensOfCollection). A successor can therefore import this
// realm, verify ownership on chain, and re-mint a byte-identical token to
// the rightful owner without any admin key, snapshot file or trusted
// operator existing anywhere in the path. Nothing in this realm can be
// switched off, redirected or upgraded by its deployer - there is
// deliberately no owner, no pause switch and no proxy.
//
// Inherited from v2 (kept verbatim below because the reasoning still
// applies):
//
// WHY A V2 AT ALL
//
// gno.land packages are immutable once deployed, so none of the fixes
// below could be retrofitted onto gno.land/r/g1hx4z2.../nft. v2 was
// deployed while v1 still held 0 minted tokens, i.e. at the only moment
// in the project's life where migrating costs nothing.
//
// WHAT CHANGED VS V1
//
//  1. Authorization no longer uses unsafe.OriginCaller().
//     v1 justified OriginCaller with a comment claiming PreviousRealm-based
//     auth "was not a reliable immediate-caller check". That misread the
//     upstream warning: the unreliable symbol is unsafe.PreviousRealm(),
//     which stack-walks. A threaded `cur realm` parameter's cur.Previous()
//     is, in gno.land's own words, "statically scoped to a crossing
//     function and cannot lie". OriginCaller is gno's tx.origin and the
//     stdlib documents it as the Solidity tx.origin phishing class: any
//     realm the user calls could invoke
//     nft.SetApprovalForAll(cross(cur), id, attacker, true) and have v1
//     attribute it to the *user*, handing an attacker every NFT that user
//     owns. Every state-changing function here derives its caller from
//     cur.Previous().Address() instead, so a malicious intermediate realm
//     can only ever act as itself.
//
//  2. Max supply is enforced against the ID counter, not the live count.
//     v1 checked `token.TokenCount() >= maxSupply`, and TokenCount() is a
//     live count that Burn decrements — so burning re-opened mint slots
//     and a 10-supply collection could mint unbounded tokens over time.
//     v2 gates on nextTokenID and tracks mintedTotal separately, so
//     "10 max supply" means 10 tokens ever, forever.
//
//  3. Per-wallet mint caps are trustless. v1's cap lived in a separate
//     nftlimits realm that nft.Mint never consulted, so it was bypassable
//     by calling Mint directly with gnokey. Here the cap is checked inside
//     Mint itself.
//
//  4. Preset artwork queues are built in, for the same reason.
//
//  5. On-chain attributes. Traits can be stored on-chain at mint time and
//     TokenMetadata() assembles a full metadata JSON document inside the
//     realm, so a token can be fully self-describing with no IPFS, no
//     gateway and no pinning service in the trust path.
//
//  6. New views the frontend previously had to brute-force:
//     TokensOfCollection (v1 had no way to list a collection's tokens
//     except probing IDs one by one) and MintedByWallet.
package nft53

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/tokens/grc721"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nftgen0"
)

const (
	// MaxRoyaltyPercent caps creator royalties at 50% of a secondary sale.
	MaxRoyaltyPercent = 50
	// MaxCollectionSupply is the platform-wide ceiling on a single
	// collection. It exists so pagination, indexing and gas stay
	// predictable, and so a "collection" stays a collection instead of an
	// unbounded minting faucet. Raising it later means a new realm.
	MaxCollectionSupply = 1000
	// MaxAttributesPerToken and MaxTraitLen bound on-chain trait storage so
	// the attributes tree can't be used as unmetered blob storage.
	MaxAttributesPerToken = 16
	MaxTraitLen           = 64
	// MaxNameLen / MaxDescriptionLen / MaxURILen bound collection metadata.
	MaxNameLen        = 64
	MaxSymbolLen      = 16
	MaxDescriptionLen = 512
	MaxURILen         = 700_000 // fully on-chain data: URIs are the point; MaxTxBytes is the real ceiling
)

// Engine is the generative engine this realm renders seeds with. It is
// recorded on a collection when the collection is marked generative, so a
// token always names the exact immutable pkgpath that produced it.
const Engine = "gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nftgen0"

// nftToken is the subset of *grc721.royaltyNFT this realm depends on.
// grc721.NewNFTWithRoyalty returns a pointer to an unexported concrete
// type, so it can't be named as a struct field type directly; Gno
// interface satisfaction is structural, so this local interface lets us
// store it in Collection.token.
type nftToken interface {
	Name() string
	Symbol() string
	TokenCount() int64
	BalanceOf(addr address) (int64, error)
	OwnerOf(tid grc721.TokenID) (address, error)
	TokenURI(tid grc721.TokenID) (string, error)
	SetTokenURI(caller address, tid grc721.TokenID, tURI grc721.TokenURI) (bool, error)
	IsApprovedForAll(owner, operator address) bool
	Approve(caller, to address, tid grc721.TokenID) error
	GetApproved(tid grc721.TokenID) (address, error)
	SetApprovalForAll(caller, operator address, approved bool) error
	TransferFrom(caller, from, to address, tid grc721.TokenID) error
	Mint(to address, tid grc721.TokenID) error
	Burn(tid grc721.TokenID) error
	RoyaltyInfo(tid grc721.TokenID, salePrice int64) (address, int64, error)
	SetTokenRoyalty(caller address, tid grc721.TokenID, info grc721.RoyaltyInfo) error
}

// Attribute is one on-chain trait of a token (OpenSea-style trait_type/value).
type Attribute struct {
	TraitType string
	Value     string
}

// Collection is one user-created NFT collection living inside this realm.
type Collection struct {
	id          string
	name        string
	symbol      string
	description string
	baseURI     string
	creator     address
	maxSupply   int64
	publicMint  bool // if true, anyone can Mint; otherwise only the creator
	royaltyPct  int64
	token       nftToken

	// nextTokenID only ever increases. It is the supply gate (see the
	// package doc, change #2): burning a token does NOT free its slot.
	nextTokenID int64
	// mintedTotal counts tokens ever minted; token.TokenCount() counts
	// tokens currently alive. They differ once anything is burned, and the
	// UI wants to show both.
	mintedTotal int64

	// maxPerWallet is a trustless per-wallet cap (0 = unlimited), checked
	// inside Mint. mintedBy tracks lifetime mints per wallet, so the cap
	// can't be reset by burning or transferring away.
	maxPerWallet int64
	mintedBy     *avl.Tree // address.String() -> int64

	// presetURIs is an optional creator-supplied reveal queue; when it is
	// non-empty, MintNext draws the next un-revealed URI instead of
	// trusting whatever URI the minter passes.
	presetURIs []string
	presetNext int

	// onchainTokens / ipfsTokens record where each minted token's artwork
	// actually lives, so the UI can show an honest "fully on-chain" badge
	// instead of trusting the creator's word. Counted at mint time over
	// lifetime mints: burning does not decrement, same as mintedTotal.
	onchainTokens int64
	ipfsTokens    int64

	// generative marks a collection whose artwork is produced by the
	// on-chain nftgen0 engine. Such tokens store only a short seed; the
	// data: URI is rebuilt at read time by TokenURI, which is what makes a
	// generative mint cost gas instead of ~2 GNOT of storage deposit.
	generative bool

	// engine pins the pkgpath of the generator this collection's tokens are
	// rendered by. Set once, when the collection is marked generative, and
	// never rewritten - see package doc, change C.
	engine string

	createdAt int64
}

// CollectionInfo is the read-only, exported view of a Collection.
// Minted is the live (un-burned) count, kept under v1's field name so the
// frontend's existing decoder keeps working; MintedTotal is new.
type CollectionInfo struct {
	ID               string
	Name             string
	Symbol           string
	Description      string
	BaseURI          string
	Creator          address
	MaxSupply        int64
	Minted           int64
	MintedTotal      int64
	PublicMint       bool
	RoyaltyPct       int64
	MaxPerWallet     int64
	PresetsTotal     int64
	PresetsRemaining int64
	CreatedAt        int64
	// New in v4. Appended at the end so existing positional decoders keep
	// working for every field before them.
	OnchainTokens int64
	IpfsTokens    int64
	StorageKind   string
	// New in v5: true when tokens are rendered from an on-chain seed.
	Generative bool
	// New in v5.1: the pinned generative engine pkgpath ("" when the
	// collection is not generative).
	Engine string
}

var (
	collections          = avl.NewTree() // id -> *Collection
	collectionsByCreator = avl.NewTree() // "creator:id" -> id
	ownerIndex           = avl.NewTree() // "owner:collectionId:tokenId" -> true
	collectionTokens     = avl.NewTree() // "collectionId:paddedTokenId" -> tokenId
	attributes           = avl.NewTree() // "collectionId:tokenId" -> []Attribute
	seeds                = avl.NewTree() // "collectionId:tokenId" -> seed string (generative tokens only)
	collCount            int64
)

// callerOf returns the identity this realm authorizes against: the
// immediate caller frame. For a direct wallet call that is the signer;
// for a cross-realm call it is the calling realm's own address, never the
// original signer. See the package doc, change #1.
func callerOf(cur realm) address {
	return cur.Previous().Address()
}

// CreateCollection registers a brand-new GRC-721 collection owned by the
// caller and returns its collection ID. Set publicMint to true to let
// anyone mint into the collection; otherwise only the creator can. Pass
// maxPerWallet = 0 for no per-wallet cap.
func CreateCollection(cur realm, name, symbol, description, baseURI string, maxSupply, royaltyPct, maxPerWallet int64, publicMint bool) string {
	caller := callerOf(cur)

	if name == "" {
		panic("name must not be empty")
	}
	if len(name) > MaxNameLen {
		panic("name too long (max " + strconv.Itoa(MaxNameLen) + " chars)")
	}
	if len(symbol) > MaxSymbolLen {
		panic("symbol too long (max " + strconv.Itoa(MaxSymbolLen) + " chars)")
	}
	if len(description) > MaxDescriptionLen {
		panic("description too long (max " + strconv.Itoa(MaxDescriptionLen) + " chars)")
	}
	if len(baseURI) > MaxURILen {
		panic("baseURI too long")
	}
	if maxSupply <= 0 {
		panic("maxSupply must be positive")
	}
	if maxSupply > MaxCollectionSupply {
		panic("maxSupply must be at most " + strconv.Itoa(MaxCollectionSupply))
	}
	if royaltyPct < 0 || royaltyPct > MaxRoyaltyPercent {
		panic("royaltyPct must be between 0 and " + strconv.Itoa(MaxRoyaltyPercent))
	}
	if maxPerWallet < 0 {
		panic("maxPerWallet must be >= 0 (0 means unlimited)")
	}

	collCount++
	id := strconv.FormatInt(collCount, 10)

	c := &Collection{
		id:           id,
		name:         name,
		symbol:       symbol,
		description:  description,
		baseURI:      baseURI,
		creator:      caller,
		maxSupply:    maxSupply,
		publicMint:   publicMint,
		royaltyPct:   royaltyPct,
		token:        grc721.NewNFTWithRoyalty(0, cur, name, symbol),
		nextTokenID:  1,
		maxPerWallet: maxPerWallet,
		mintedBy:     avl.NewTree(),
		createdAt:    runtime.ChainHeight(),
	}
	collections.Set(id, c)
	collectionsByCreator.Set(caller.String()+":"+id, id)

	chain.Emit(
		"CollectionCreated",
		"id", id,
		"creator", caller.String(),
		"name", name,
		"symbol", symbol,
	)

	return id
}

// Mint mints the next token in a collection to the caller and returns the
// new token ID.
func Mint(cur realm, collectionID, tokenURI string) string {
	assertNotGenerative(collectionID)
	return mint(cur, callerOf(cur), collectionID, tokenURI, "")
}

// MintWithTraits mints like Mint and additionally records on-chain traits.
// traits is a compact "trait=value;trait=value" string because gno.land's
// vm.MsgCall only carries scalar string arguments — the same reason batch
// minting loops single calls instead of passing an array.
// Only the collection's creator may hand-write traits: a stranger minting
// into a public collection must not be able to award themselves
// "Rarity=Legendary" and poison the marketplace filter (package doc,
// change B). Public minters can still mint - they just cannot dictate
// metadata that the market prices.
func MintWithTraits(cur realm, collectionID, tokenURI, traits string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if c.generative {
		panic("this collection is generative; its traits come from the engine - use MintGenerative")
	}
	if traits != "" && caller != c.creator {
		panic("only the collection's creator can set traits by hand; use Mint instead")
	}
	return mint(cur, caller, collectionID, tokenURI, traits)
}

// MintNext draws the next un-revealed URI from the collection's preset
// queue and mints it to the caller, so the minter has no say over which
// artwork they receive.
func MintNext(cur realm, collectionID string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if c.generative {
		panic("this collection is generative; use MintGenerative")
	}
	if len(c.presetURIs) == 0 {
		panic("this collection has no preset artwork queue - mint normally instead")
	}
	if c.presetNext >= len(c.presetURIs) {
		panic("no preset artwork left to reveal - the queue is exhausted")
	}
	uri := c.presetURIs[c.presetNext]
	c.presetNext++
	return mint(cur, caller, collectionID, uri, "")
}

func mint(cur realm, caller address, collectionID, tokenURI, traits string) string {
	c := mustGetCollection(collectionID)

	if !c.publicMint && caller != c.creator {
		panic("minting into this collection is restricted to its creator")
	}
	// Supply gate on the ID counter, not the live count: burning must not
	// re-open a slot (see package doc, change #2).
	if c.nextTokenID > c.maxSupply {
		panic("collection has reached its max supply")
	}
	if len(tokenURI) > MaxURILen {
		panic("tokenURI too long")
	}

	// Trustless per-wallet cap, counted over lifetime mints so it survives
	// burning and transferring away (see package doc, change #3).
	if c.maxPerWallet > 0 {
		if mintedByWallet(c, caller) >= c.maxPerWallet {
			panic("wallet has reached this collection's per-wallet mint limit of " +
				strconv.FormatInt(c.maxPerWallet, 10))
		}
	}

	attrs := parseTraits(traits)

	tidStr := strconv.FormatInt(c.nextTokenID, 10)
	c.nextTokenID++
	c.mintedTotal++
	tid := grc721.TokenID(tidStr)

	if err := c.token.Mint(caller, tid); err != nil {
		panic(err)
	}
	if tokenURI != "" {
		if _, err := c.token.SetTokenURI(caller, tid, grc721.TokenURI(tokenURI)); err != nil {
			panic(err)
		}
	}
	if c.royaltyPct > 0 {
		// Freshly minted tokens are owned by caller, so caller satisfies
		// SetTokenRoyalty's "caller must be current owner" check.
		if err := c.token.SetTokenRoyalty(caller, tid, grc721.RoyaltyInfo{
			PaymentAddress: c.creator,
			Percentage:     c.royaltyPct,
		}); err != nil {
			panic(err)
		}
	}

	// Where does this token's artwork live? A token with no URI of its own
	// inherits the collection's baseURI, so classify whichever one applies.
	effURI := tokenURI
	if effURI == "" {
		effURI = c.baseURI
	}
	if strings.HasPrefix(effURI, "data:") {
		c.onchainTokens++
	} else if strings.HasPrefix(effURI, "ipfs://") {
		c.ipfsTokens++
	}

	c.mintedBy.Set(caller.String(), mintedByWallet(c, caller)+1)
	ownerIndex.Set(caller.String()+":"+collectionID+":"+tidStr, true)
	collectionTokens.Set(collectionID+":"+padID(tidStr), tidStr)
	if len(attrs) > 0 {
		attributes.Set(collectionID+":"+tidStr, attrs)
	}

	chain.Emit(
		"NFTMinted",
		"collection", collectionID,
		"tokenId", tidStr,
		"to", caller.String(),
	)

	return tidStr
}

// SetGenerative marks (or unmarks) a collection as generative, meaning
// its tokens are minted with MintGenerative and rendered from a seed by
// the on-chain nftgen0 engine. Creator-only, and refused once anything
// has been minted so a collection can never change what its existing
// tokens look like.
func SetGenerative(cur realm, collectionID string, generative bool) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can change its generative mode")
	}
	if c.mintedTotal > 0 {
		panic("collection already has minted tokens; generative mode is fixed")
	}
	c.generative = generative
	if generative {
		c.engine = Engine
	} else {
		c.engine = ""
	}
}

// MintGenerative mints the next token of a generative collection to the
// caller. No artwork is stored: the token keeps a seed, and its traits
// are the ones nftgen0 derives from that same seed, so the trait filter
// in the marketplace keeps working exactly as it does for stored art.
func MintGenerative(cur realm, collectionID string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if !c.generative {
		panic("this collection is not generative; use Mint or MintNext instead")
	}

	seed := nftgen0.SeedFor(collectionID, strconv.FormatInt(c.nextTokenID, 10))
	// The traits are NOT written to the attributes tree: they are a pure
	// function of this seed and TokenAttributes derives them on read. v5
	// stored both and paid 12-20 KB of deposit per token for the privilege
	// (package doc, change A).
	tidStr := mint(cur, caller, collectionID, "", "")

	seeds.Set(collectionID+":"+tidStr, seed)
	// The artwork is produced and served entirely by on-chain code, so it
	// is on-chain in the strongest sense - there is not even a stored blob
	// that could rot. mint() classifies by URI and a generative mint has
	// none, so it only counted this token if the collection's baseURI is
	// itself a data: URI; guard against counting it twice.
	if !strings.HasPrefix(c.baseURI, "data:") {
		c.onchainTokens++
	}

	chain.Emit(
		"GenerativeMinted",
		"collection", collectionID,
		"tokenId", tidStr,
		"seed", seed,
		"to", caller.String(),
	)

	return tidStr
}

// QueuePresetURI appends one tokenURI to a collection's reveal queue.
// Creator-only.
func QueuePresetURI(cur realm, collectionID, uri string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can queue preset artwork")
	}
	if uri == "" {
		panic("uri must not be empty")
	}
	if len(uri) > MaxURILen {
		panic("uri too long")
	}
	if int64(len(c.presetURIs)) >= c.maxSupply {
		panic("preset queue is already as large as the collection's max supply")
	}
	c.presetURIs = append(c.presetURIs, uri)
}

// SetMaxPerWallet sets (0 clears) the trustless per-wallet mint cap.
// Creator-only. Lowering it never retroactively invalidates existing
// tokens; it only blocks further mints by wallets already at or over it.
func SetMaxPerWallet(cur realm, collectionID string, max int64) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can set its mint limit")
	}
	if max < 0 {
		panic("max must be >= 0 (0 clears the limit)")
	}
	c.maxPerWallet = max
}

// Approve approves `to` to transfer a single token on the caller's behalf.
func Approve(cur realm, collectionID, tokenID string, to address) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if err := c.token.Approve(caller, to, grc721.TokenID(tokenID)); err != nil {
		panic(err)
	}
}

// SetApprovalForAll grants/revokes operator permission across all of the
// caller's tokens in one collection (e.g. approving the marketplace realm
// once instead of per-token).
func SetApprovalForAll(cur realm, collectionID string, operator address, approved bool) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if err := c.token.SetApprovalForAll(caller, operator, approved); err != nil {
		panic(err)
	}
}

// TransferFrom transfers a token from `from` to `to`. The caller must be
// the owner or an approved operator/spender — which is how nftmarket2 and
// nftoffers2 move tokens: they call this via cross(cur), so the caller
// seen here is the marketplace realm's own address, exactly the identity
// the seller approved.
func TransferFrom(cur realm, collectionID, tokenID string, from, to address) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	tid := grc721.TokenID(tokenID)

	if err := c.token.TransferFrom(caller, from, to, tid); err != nil {
		panic(err)
	}

	ownerIndex.Remove(from.String() + ":" + collectionID + ":" + tokenID)
	ownerIndex.Set(to.String()+":"+collectionID+":"+tokenID, true)

	chain.Emit(
		"Transfer",
		"collection", collectionID,
		"tokenId", tokenID,
		"from", from.String(),
		"to", to.String(),
	)
}

// Burn destroys a token. Caller must be the token's current owner. The
// burned token's supply slot is never reused.
func Burn(cur realm, collectionID, tokenID string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	tid := grc721.TokenID(tokenID)

	owner, err := c.token.OwnerOf(tid)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token owner can burn it")
	}
	if err := c.token.Burn(tid); err != nil {
		panic(err)
	}

	ownerIndex.Remove(owner.String() + ":" + collectionID + ":" + tokenID)
	collectionTokens.Remove(collectionID + ":" + padID(tokenID))
	attributes.Remove(collectionID + ":" + tokenID)
	seeds.Remove(collectionID + ":" + tokenID)

	chain.Emit("Burn", "collection", collectionID, "tokenId", tokenID, "from", owner.String())
}

// Read-only views.

// GetCollection returns the exported view of one collection.
func GetCollection(collectionID string) CollectionInfo {
	return toInfo(mustGetCollection(collectionID))
}

// ListCollections returns up to `limit` collections starting at `offset`,
// ordered by collection ID (creation order).
func ListCollections(offset, limit int64) []CollectionInfo {
	out := make([]CollectionInfo, 0, limit)
	collections.IterateByOffset(int(offset), int(limit), func(key string, value any) bool {
		out = append(out, toInfo(value.(*Collection)))
		return false
	})
	return out
}

// CollectionCount returns the total number of collections ever created.
func CollectionCount() int64 {
	return collCount
}

// TokensOfOwner returns "collectionId:tokenId" pairs for every token the
// given address owns, across every collection in this realm.
func TokensOfOwner(owner address) []string {
	var out []string
	prefix := owner.String() + ":"
	ownerIndex.Iterate(prefix, owner.String()+";", func(key string, value any) bool {
		out = append(out, key[len(prefix):])
		return false
	})
	return out
}

// TokensOfCollection returns the live token IDs of one collection in
// ascending numeric order. v1 had no such view at all — the frontend had
// to probe OwnerOf(1..maxSupply) one RPC call at a time.
func TokensOfCollection(collectionID string, offset, limit int64) []string {
	mustGetCollection(collectionID)
	var out []string
	var seen int64
	prefix := collectionID + ":"
	collectionTokens.Iterate(prefix, collectionID+";", func(key string, value any) bool {
		if seen < offset {
			seen++
			return false
		}
		if limit > 0 && int64(len(out)) >= limit {
			return true
		}
		out = append(out, value.(string))
		seen++
		return false
	})
	return out
}

// MintedByWallet returns how many tokens of a collection an address has
// minted over its lifetime (the number the per-wallet cap is checked
// against — not the same as the current balance).
func MintedByWallet(collectionID string, wallet address) int64 {
	return mintedByWallet(mustGetCollection(collectionID), wallet)
}

// BalanceOf returns how many tokens of one collection an address owns.
func BalanceOf(collectionID string, owner address) int64 {
	bal, err := mustGetCollection(collectionID).token.BalanceOf(owner)
	if err != nil {
		panic(err)
	}
	return bal
}

// OwnerOf returns the current owner of a token.
func OwnerOf(collectionID, tokenID string) (address, error) {
	return mustGetCollection(collectionID).token.OwnerOf(grc721.TokenID(tokenID))
}

// TokenURI returns the metadata URI of a token.
//
// For a generative token nothing is stored but a short seed: the data:
// URI is rebuilt here by the nftgen0 engine on every read. Storing a
// 4-5 KB base64 SVG per token cost roughly 2.1 GNOT of storage deposit
// in v4; a seed costs a few dozen bytes, and because the generator is
// deterministic the artwork is byte-identical forever.
func TokenURI(collectionID, tokenID string) (string, error) {
	if seed, ok := seeds.Get(collectionID + ":" + tokenID).(string); ok {
		return nftgen0.DataURI(seed), nil
	}
	return mustGetCollection(collectionID).token.TokenURI(grc721.TokenID(tokenID))
}

// TokenSeed returns the generative seed of a token, or "" when the token
// stores an ordinary URI.
func TokenSeed(collectionID, tokenID string) string {
	if seed, ok := seeds.Get(collectionID + ":" + tokenID).(string); ok {
		return seed
	}
	return ""
}

// TokenAttributes returns a token's traits.
//
// Stored traits win when they exist, so tokens minted with explicit traits
// (and any token carried over from an older realm) keep behaving exactly as
// before. A generative token has none: its traits are rebuilt here from its
// seed, which is both cheaper and unforgeable - see package doc, changes A
// and B. The output is byte-identical to what v5 used to persist, which the
// realm's test suite asserts seed by seed.
func TokenAttributes(collectionID, tokenID string) []Attribute {
	if v := attributes.Get(collectionID + ":" + tokenID); v != nil {
		return v.([]Attribute)
	}
	if seed, ok := seeds.Get(collectionID + ":" + tokenID).(string); ok {
		return deriveAttributes(seed)
	}
	return nil
}

// deriveAttributes rebuilds the trait list for a seed. It mirrors
// nftgen0.TraitString field for field; the test suite pins that equality so
// the two can never drift apart silently.
func deriveAttributes(seed string) []Attribute {
	tr := nftgen0.TraitsOf(seed)
	aura := "No"
	if tr.Aura {
		aura = "Yes"
	}
	return []Attribute{
		{TraitType: "Palette", Value: tr.Palette},
		{TraitType: "Shape", Value: tr.Shape},
		{TraitType: "Ground", Value: tr.Ground},
		{TraitType: "Elements", Value: strconv.Itoa(tr.Elements)},
		{TraitType: "Symmetry", Value: strconv.Itoa(tr.Symmetry)},
		{TraitType: "Aura", Value: aura},
		{TraitType: "Rarity", Value: tr.Rarity},
	}
}

// TokenMetadata assembles a complete metadata JSON document for a token
// inside the realm, so a fully on-chain token needs no IPFS, no gateway
// and no pinning service to be readable.
func TokenMetadata(collectionID, tokenID string) string {
	c := mustGetCollection(collectionID)
	uri, err := TokenURI(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	_ = c

	out := "{\"name\":\"" + jsonEscape(c.name+" #"+tokenID) + "\""
	out += ",\"description\":\"" + jsonEscape(c.description) + "\""
	out += ",\"image\":\"" + jsonEscape(uri) + "\""
	out += ",\"attributes\":["
	for i, a := range TokenAttributes(collectionID, tokenID) {
		if i > 0 {
			out += ","
		}
		out += "{\"trait_type\":\"" + jsonEscape(a.TraitType) +
			"\",\"value\":\"" + jsonEscape(a.Value) + "\"}"
	}
	out += "]}"
	return out
}

// GetApproved returns the address approved for a single token, if any.
func GetApproved(collectionID, tokenID string) (address, error) {
	return mustGetCollection(collectionID).token.GetApproved(grc721.TokenID(tokenID))
}

// IsApprovedForAll reports whether operator can manage all of owner's
// tokens in one collection.
func IsApprovedForAll(collectionID string, owner, operator address) bool {
	return mustGetCollection(collectionID).token.IsApprovedForAll(owner, operator)
}

// RoyaltyInfo returns the payment address and royalty amount owed for a
// sale of the given token at salePrice.
func RoyaltyInfo(collectionID, tokenID string, salePrice int64) (address, int64, error) {
	return mustGetCollection(collectionID).token.RoyaltyInfo(grc721.TokenID(tokenID), salePrice)
}

// Render implements the gno.land realm home-page convention so the
// factory is browsable from gnoweb even without the dedicated frontend.
func Render(path string) string {
	if path != "" {
		v := collections.Get(path)
		if v == nil {
			return "# 404\n\ncollection not found: " + path
		}
		return renderCollection(v.(*Collection))
	}

	out := ufmt.Sprintf("# gnoNFT Factory v5.3\n\n%d collection(s)\n\n", collCount)
	collections.Iterate("", "", func(key string, value any) bool {
		c := value.(*Collection)
		out += ufmt.Sprintf(
			"- [#%s %s (%s)](:%s) - %d/%d minted, by %s\n",
			c.id, c.name, c.symbol, c.id, c.mintedTotal, c.maxSupply, c.creator.String(),
		)
		return false
	})
	return out
}

func renderCollection(c *Collection) string {
	out := ufmt.Sprintf("# %s (%s)\n\n%s\n\n", c.name, c.symbol, c.description)
	out += ufmt.Sprintf("- Creator: %s\n", c.creator.String())
	out += ufmt.Sprintf("- Minted: %d / %d\n", c.mintedTotal, c.maxSupply)
	out += ufmt.Sprintf("- Currently live: %d\n", c.token.TokenCount())
	out += ufmt.Sprintf("- Public mint: %t\n", c.publicMint)
	out += ufmt.Sprintf("- Royalty: %d%%\n", c.royaltyPct)
	if c.maxPerWallet > 0 {
		out += ufmt.Sprintf("- Max per wallet: %d\n", c.maxPerWallet)
	}
	if total := len(c.presetURIs); total > 0 {
		out += ufmt.Sprintf("- Presets revealed: %d / %d\n", c.presetNext, total)
	}
	return out
}

// Internal helpers.

func mintedByWallet(c *Collection, wallet address) int64 {
	v := c.mintedBy.Get(wallet.String())
	if v == nil {
		return 0
	}
	return v.(int64)
}

// parseTraits turns "Background=Blue;Eyes=Laser" into attributes. Empty
// segments are skipped; a segment with no '=' is rejected outright rather
// than silently stored, so a typo can't be minted into a token forever.
func parseTraits(traits string) []Attribute {
	if traits == "" {
		return nil
	}
	var out []Attribute
	for _, seg := range strings.Split(traits, ";") {
		seg = strings.TrimSpace(seg)
		if seg == "" {
			continue
		}
		idx := strings.Index(seg, "=")
		if idx <= 0 || idx == len(seg)-1 {
			panic("malformed trait \"" + seg + "\": expected trait=value pairs separated by ';'")
		}
		k := strings.TrimSpace(seg[:idx])
		v := strings.TrimSpace(seg[idx+1:])
		if len(k) > MaxTraitLen || len(v) > MaxTraitLen {
			panic("trait name/value too long (max " + strconv.Itoa(MaxTraitLen) + " chars)")
		}
		out = append(out, Attribute{TraitType: k, Value: v})
		if len(out) > MaxAttributesPerToken {
			panic("too many traits (max " + strconv.Itoa(MaxAttributesPerToken) + ")")
		}
	}
	return out
}

// padID zero-pads a numeric token ID so the collectionTokens tree sorts
// numerically rather than lexicographically ("10" must come after "2").
func padID(id string) string {
	const width = 12
	if len(id) >= width {
		return id
	}
	return "000000000000"[:width-len(id)] + id
}

func jsonEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

func toInfo(c *Collection) CollectionInfo {
	presetsTotal := int64(len(c.presetURIs))
	remaining := presetsTotal - int64(c.presetNext)
	if remaining < 0 {
		remaining = 0
	}
	return CollectionInfo{
		ID:               c.id,
		Name:             c.name,
		Symbol:           c.symbol,
		Description:      c.description,
		BaseURI:          c.baseURI,
		Creator:          c.creator,
		MaxSupply:        c.maxSupply,
		Minted:           c.token.TokenCount(),
		MintedTotal:      c.mintedTotal,
		PublicMint:       c.publicMint,
		RoyaltyPct:       c.royaltyPct,
		MaxPerWallet:     c.maxPerWallet,
		PresetsTotal:     presetsTotal,
		PresetsRemaining: remaining,
		CreatedAt:        c.createdAt,
		OnchainTokens:    c.onchainTokens,
		IpfsTokens:       c.ipfsTokens,
		StorageKind:      storageKind(c),
		Generative:       c.generative,
		Engine:           c.engine,
	}
}

// storageKind reports where a collection's artwork lives:
//
//	"onchain"  every minted token is a data: URI - nothing off-chain to rot
//	"ipfs"     every minted token points at ipfs://
//	"external" plain http(s) links
//	"mixed"    a bit of both
//	"unknown"  nothing minted yet and no baseURI hint
//
// Before the first mint the baseURI is the only evidence available, so it
// is used as the hint; after that the per-token counters decide.
func storageKind(c *Collection) string {
	if c.mintedTotal == 0 {
		if strings.HasPrefix(c.baseURI, "data:") {
			return "onchain"
		}
		if strings.HasPrefix(c.baseURI, "ipfs://") {
			return "ipfs"
		}
		if c.baseURI == "" {
			return "unknown"
		}
		return "external"
	}
	if c.onchainTokens == c.mintedTotal {
		return "onchain"
	}
	if c.ipfsTokens == c.mintedTotal {
		return "ipfs"
	}
	if c.onchainTokens == 0 && c.ipfsTokens == 0 {
		return "external"
	}
	return "mixed"
}

// CollectionStorageKind exposes storageKind as a standalone view so the UI
// can badge a collection without decoding a whole CollectionInfo.
func CollectionStorageKind(collectionID string) string {
	return storageKind(mustGetCollection(collectionID))
}

// assertNotGenerative refuses hand-minting into a generative collection, so
// "every token here is derived from its seed" stays a checkable claim.
func assertNotGenerative(collectionID string) {
	if mustGetCollection(collectionID).generative {
		panic("this collection is generative; use MintGenerative")
	}
}

func mustGetCollection(id string) *Collection {
	v := collections.Get(id)
	if v == nil {
		panic("collection not found: " + id)
	}
	return v.(*Collection)
}
